window.__saMergeCourse({id:'kpk-class10-chemistry', board:'kp', title:'Chemistry', urdu:'کیمسٹری', class:'Class 10', icon:'🧪', desc:'KP Board Class 10 Chemistry — full syllabus with lessons and quizzes.', chapters:[
{id:'kpk-c10-che-ch9', title:'Chemical Equilibrium', urdu:'کیمیائی توازن', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch9-l1', title:'Reversible Reactions and Dynamic Equilibrium', html:'<h3>Reversible vs Irreversible</h3><p><strong>Irreversible</strong> reactions go to completion (burning of paper). <strong>Reversible</strong> reactions go both ways: N₂ + 3H₂ ⇌ 2NH₃.</p><h3>Dynamic Equilibrium</h3><p>In a <strong>closed system</strong>, a reversible reaction reaches <strong>dynamic equilibrium</strong>: forward and reverse rates are <strong>equal</strong>, so concentrations stay constant — but molecules keep reacting. It is dynamic, not dead.</p>'},
{id:'kpk-c10-che-ch9-l2', title:'Law of Mass Action and Kc', html:'<h3>Equilibrium Constant</h3><p>For aA + bB ⇌ cC + dD:</p><blockquote>Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ</blockquote><p>For N₂ + 3H₂ ⇌ 2NH₃: Kc = [NH₃]²/([N₂][H₂]³).</p><h3>What Kc Tells Us</h3><ul><li><strong>Large Kc:</strong> mostly products at equilibrium.</li><li><strong>Small Kc:</strong> mostly reactants.</li><li>Kc is constant at a given temperature — it changes only with <strong>temperature</strong>.</li></ul>'},
{id:'kpk-c10-che-ch9-l3', title:'Le Chatelier’s Principle and Industry', html:'<h3>The Principle</h3><p><em>If a stress is applied to an equilibrium, the system shifts to undo it:</em></p><ul><li><strong>Concentration:</strong> adding reactant shifts right (more product).</li><li><strong>Pressure:</strong> shifts towards <strong>fewer gas moles</strong>.</li><li><strong>Temperature:</strong> shifts in the <strong>endothermic</strong> direction.</li></ul><h3>Industrial Uses</h3><ul><li><strong>Haber process</strong> (NH₃): high pressure, ~450°C, iron catalyst — favours the 4→2 gas-mole, exothermic forward reaction.</li><li><strong>Contact process</strong> (H₂SO₄): 2SO₂ + O₂ ⇌ 2SO₃ with V₂O₅ catalyst.</li></ul>'}],
quiz:[
{q:'Dynamic equilibrium occurs in a:', options:['Open system','Closed system','Vacuum','Plasma'], answer:1, explain:'Products must stay in the vessel for the reverse reaction to balance the forward one.'},
{q:'At dynamic equilibrium:', options:['Reactions stop','Forward and reverse rates are equal','Only products exist','Concentrations are zero'], answer:1, explain:'Equal opposing rates keep concentrations constant while molecules keep reacting.'},
{q:'For N₂ + 3H₂ ⇌ 2NH₃, Kc equals:', options:['[NH₃]/([N₂][H₂])','[NH₃]²/([N₂][H₂]³)','([N₂][H₂]³)/[NH₃]²','[N₂][H₂]/[NH₃]'], answer:1, explain:'Products over reactants, each raised to its coefficient.'},
{q:'A very large Kc means the equilibrium mixture is:', options:['Mostly reactants','Mostly products','Half and half','Empty'], answer:1, explain:'Large Kc = products strongly favoured.'},
{q:'Kc changes only when ___ changes.', options:['Pressure','Concentration','Temperature','Volume'], answer:2, explain:'Kc is temperature-dependent; other stresses shift position, not Kc.'},
{q:'Increasing pressure on N₂ + 3H₂ ⇌ 2NH₃ shifts equilibrium:', options:['Left','Right','Nowhere','It explodes'], answer:1, explain:'Right side has fewer gas moles (2 vs 4), favoured by pressure.'},
{q:'For an exothermic forward reaction, raising temperature shifts equilibrium:', options:['Right','Left','Nowhere','Both ways'], answer:1, explain:'Heat acts like a product; adding it drives the reverse (endothermic) direction.'},
{q:'The Haber process uses ___ as catalyst.', options:['V₂O₅','Iron','Platinum','Nickel'], answer:1, explain:'Finely divided iron speeds ammonia formation.'},
{q:'The Contact process manufactures:', options:['Ammonia','Sulphuric acid','Nitric acid','Urea'], answer:1, explain:'2SO₂ + O₂ ⇌ 2SO₃ (V₂O₅), then SO₃ → H₂SO₄.'},
{q:'Adding more H₂ to the Haber equilibrium will:', options:['Make more N₂','Make more NH₃','Stop the reaction','Destroy the catalyst'], answer:1, explain:'Le Chatelier: added reactant is consumed, shifting right.'}
]},
{id:'kpk-c10-che-ch10', title:'Acids, Bases and Salts', urdu:'تیزاب، اساس اور نمکیات', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch10-l1', title:'Concepts of Acids and Bases', html:'<h3>Three Definitions</h3><ul><li><strong>Arrhenius:</strong> acid gives H⁺ in water; base gives OH⁻ in water.</li><li><strong>Bronsted–Lowry:</strong> acid = <strong>proton donor</strong>; base = <strong>proton acceptor</strong> (HCl + NH₃ → NH₄⁺ + Cl⁻).</li><li><strong>Lewis:</strong> acid = <strong>electron-pair acceptor</strong>; base = <strong>electron-pair donor</strong> (widest definition).</li></ul><h3>Strength</h3><p><strong>Strong</strong> acids/bases ionise fully (HCl, NaOH); <strong>weak</strong> ones partly (CH₃COOH, NH₄OH).</p>'},
{id:'kpk-c10-che-ch10-l2', title:'pH Scale and Indicators', html:'<h3>pH Scale</h3><blockquote>pH = −log[H⁺];  pH + pOH = 14</blockquote><p>pH &lt; 7 acidic, = 7 neutral, &gt; 7 basic. Each step is <strong>10×</strong> the acidity.</p><h3>Indicators</h3><table><tr><th>Indicator</th><th>In acid</th><th>In base</th></tr><tr><td>Litmus</td><td>Red</td><td>Blue</td></tr><tr><td>Phenolphthalein</td><td>Colourless</td><td>Pink</td></tr><tr><td>Methyl orange</td><td>Red</td><td>Yellow</td></tr></table>'},
{id:'kpk-c10-che-ch10-l3', title:'Salts', html:'<h3>Formation</h3><p><strong>Acid + base → salt + water</strong> (neutralisation). Also: acid + metal, acid + carbonate.</p><h3>Types</h3><ul><li><strong>Normal:</strong> NaCl, KNO₃.</li><li><strong>Acidic:</strong> NaHSO₄ (has replaceable H).</li><li><strong>Basic:</strong> Mg(OH)Cl (has OH).</li><li><strong>Double:</strong> potash alum; <strong>mixed:</strong> bleaching powder Ca(OCl)Cl.</li></ul><h3>Uses</h3><p>NaCl (food, chemicals), Na₂CO₃ (washing soda — glass, soap), NaHCO₃ (baking soda — baking, antacid), CaSO₄·2H₂O (plaster of Paris).</p>'}],
quiz:[
{q:'According to Bronsted–Lowry, an acid is a:', options:['Electron donor','Proton donor','Proton acceptor','Hydroxide donor'], answer:1, explain:'Acids donate H⁺; bases accept them.'},
{q:'A Lewis base is an:', options:['Proton donor','Electron-pair donor','Electron-pair acceptor','Neutron donor'], answer:1, explain:'Lewis widens the idea to electron pairs.'},
{q:'Which is a weak acid?', options:['HCl','H₂SO₄','CH₃COOH','HNO₃'], answer:2, explain:'Acetic acid ionises only partly in water.'},
{q:'A solution with pH 3 compared to pH 5 is:', options:['2× as acidic','100× as acidic','10× as acidic','Less acidic'], answer:1, explain:'Each pH unit = 10×; two units = 100×.'},
{q:'Phenolphthalein in a basic solution turns:', options:['Red','Pink','Yellow','Blue'], answer:1, explain:'Colourless in acid, pink in base.'},
{q:'Methyl orange in acid is:', options:['Yellow','Red','Pink','Green'], answer:1, explain:'Red in acid, yellow in base.'},
{q:'Acid + base →', options:['Salt + hydrogen','Salt + water','Salt + oxygen','Water only'], answer:1, explain:'Neutralisation gives salt and water.'},
{q:'NaHSO₄ is an example of a ___ salt.', options:['Normal','Acidic','Basic','Double'], answer:1, explain:'It still has a replaceable hydrogen.'},
{q:'Washing soda is:', options:['NaHCO₃','Na₂CO₃','CaCO₃','NaCl'], answer:1, explain:'Sodium carbonate — used in glass and soap.'},
{q:'Plaster of Paris is:', options:['CaSO₄·2H₂O','CaSO₄·½H₂O','CaO','Ca(OH)₂'], answer:1, explain:'Hemihydrate of calcium sulphate; gypsum is the dihydrate.'}
]},
{id:'kpk-c10-che-ch11', title:'Organic Chemistry', urdu:'نامیاتی کیمسٹری', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch11-l1', title:'Organic Compounds and Their Sources', html:'<h3>What Makes Them Organic?</h3><p><strong>Organic compounds</strong> contain carbon, usually with hydrogen (simple oxides like CO₂ and carbonates are the exceptions). Millions exist because carbon <strong>catenates</strong> (forms long chains) and forms four covalent bonds.</p><h3>Sources</h3><ul><li><strong>Natural gas and petroleum:</strong> hydrocarbons.</li><li><strong>Coal:</strong> aromatic compounds.</li><li><strong>Plants and animals:</strong> carbohydrates, proteins, fats, urea (first lab-made organic compound — Wöhler, 1828).</li></ul>'},
{id:'kpk-c10-che-ch11-l2', title:'Classification', html:'<h3>By Carbon Skeleton</h3><ul><li><strong>Open chain (acyclic):</strong> straight or branched chains.</li><li><strong>Closed chain (cyclic):</strong> rings — <strong>alicyclic</strong> (cyclohexane) or <strong>aromatic</strong> (benzene).</li><li><strong>Heterocyclic:</strong> rings with N, O or S (pyridine).</li></ul><h3>Homologous Series</h3><p>A family with the same functional group differing by <strong>−CH₂−</strong>: similar chemical properties, gradual physical change. Example: alkanes (methane, ethane, propane…).</p>'},
{id:'kpk-c10-che-ch11-l3', title:'Functional Groups', html:'<h3>Key Functional Groups</h3><table><tr><th>Group</th><th>Formula</th><th>Family</th></tr><tr><td>Hydroxyl</td><td>−OH</td><td>Alcohols</td></tr><tr><td>Carboxyl</td><td>−COOH</td><td>Carboxylic acids</td></tr><tr><td>Aldehydic</td><td>−CHO</td><td>Aldehydes</td></tr><tr><td>Keto</td><td>&gt;C=O</td><td>Ketones</td></tr><tr><td>Amino</td><td>−NH₂</td><td>Amines</td></tr><tr><td>Halo</td><td>−X</td><td>Alkyl halides</td></tr></table><p>The functional group decides the compound’s characteristic reactions.</p>'}],
quiz:[
{q:'Organic compounds must contain:', options:['Oxygen','Carbon','Nitrogen','Sulphur'], answer:1, explain:'Carbon is the defining element of organic chemistry.'},
{q:'Who first synthesised an organic compound (urea) in the lab?', options:['Berzelius','Wöhler','Kekulé','Lavoisier'], answer:1, explain:'Wöhler (1828) ended the vital-force theory.'},
{q:'Carbon forms millions of compounds mainly because of:', options:['Ionic bonding','Catenation and tetravalency','Radioactivity','Magnetism'], answer:1, explain:'Long chains/rings + four bonds = endless variety.'},
{q:'Benzene is an example of a ___ compound.', options:['Alicyclic','Aromatic','Heterocyclic','Open-chain'], answer:1, explain:'Its delocalised ring makes it aromatic.'},
{q:'Members of a homologous series differ by:', options:['−CH₃','−CH₂−','−OH','−COOH'], answer:1, explain:'Each step adds one methylene group.'},
{q:'The functional group of carboxylic acids is:', options:['−OH','−COOH','−CHO','−NH₂'], answer:1, explain:'The carboxyl group gives acidic properties.'},
{q:'Compounds containing −CHO are called:', options:['Ketones','Aldehydes','Alcohols','Acids'], answer:1, explain:'The aldehydic group defines aldehydes.'},
{q:'Natural gas is mainly:', options:['Butane','Methane','Ethene','Benzene'], answer:1, explain:'Natural gas is ~90% methane.'},
{q:'Pyridine is heterocyclic because its ring contains:', options:['Only carbon','Nitrogen','Oxygen','Sulphur'], answer:1, explain:'Hetero = different atom (N) in the ring.'},
{q:'CO₂ is considered inorganic because:', options:['It has no hydrogen typical of organics','It is a gas','It is poisonous','It has oxygen'], answer:0, explain:'Simple carbon oxides/carbonates are classed as inorganic.'}
]},
{id:'kpk-c10-che-ch12', title:'Hydrocarbons', urdu:'ہائیڈروکاربن', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch12-l1', title:'Alkanes', html:'<h3>General Formula: CₙH₂ₙ₊₂</h3><p><strong>Alkanes</strong> have only single bonds — <strong>saturated</strong> hydrocarbons. Methane (CH₄) is <strong>tetrahedral</strong> (109.5°).</p><ul><li>First members: methane, ethane, propane, butane.</li><li><strong>Unreactive</strong> (paraffins) — undergo <strong>substitution</strong> (e.g. chlorination in sunlight) and <strong>combustion</strong>.</li></ul><p>CH₄ + 2O₂ → CO₂ + 2H₂O (complete combustion).</p>'},
{id:'kpk-c10-che-ch12-l2', title:'Alkenes and Alkynes', html:'<h3>Alkenes: CₙH₂ₙ</h3><p>One <strong>double bond</strong> — <strong>unsaturated</strong>. Ethene (CH₂=CH₂) undergoes <strong>addition</strong> reactions: hydrogenation (→ ethane), halogenation, and <strong>polymerisation</strong> (→ polythene).</p><h3>Alkynes: CₙH₂ₙ₋₂</h3><p>One <strong>triple bond</strong>. Ethyne/acetylene (CH≡CH) burns with a very hot flame — used in <strong>oxy-acetylene welding</strong>.</p><h3>Test</h3><p><strong>Bromine water</strong> is decolourised by alkenes/alkynes but not by alkanes.</p>'},
{id:'kpk-c10-che-ch12-l3', title:'Petroleum Refining', html:'<h3>Fractional Distillation</h3><p>Crude oil is separated by boiling ranges:</p><ul><li><strong>Refinery gas</strong> (fuel), <strong>gasoline/petrol</strong> (cars), <strong>kerosene</strong> (jets), <strong>diesel</strong> (trucks), <strong>fuel oil</strong>, <strong>bitumen</strong> (roads).</li></ul><p>Lighter fractions rise higher in the tower. <strong>Knocking</strong> in engines is reduced by high-octane fuel.</p>'}],
quiz:[
{q:'The general formula of alkanes is:', options:['CₙH₂ₙ','CₙH₂ₙ₊₂','CₙH₂ₙ₋₂','CₙHₙ'], answer:1, explain:'Saturated: maximum hydrogens.'},
{q:'Methane’s shape is:', options:['Linear','Tetrahedral','Planar','Bent'], answer:1, explain:'Four bond pairs → tetrahedral, 109.5°.'},
{q:'Alkenes are unsaturated because they contain a:', options:['Single bond','Double bond','Triple bond','Ionic bond'], answer:1, explain:'The double bond can add more atoms.'},
{q:'Ethene polymerises to form:', options:['PVC','Polythene','Teflon','Nylon'], answer:1, explain:'n(CH₂=CH₂) → polythene.'},
{q:'Acetylene is used in:', options:['Cooking','Oxy-acetylene welding','Refrigeration','Balloons'], answer:1, explain:'Its flame is extremely hot.'},
{q:'Bromine water is decolourised by:', options:['Methane','Ethene','Propane','Butane'], answer:1, explain:'Alkenes add bromine across the double bond.'},
{q:'The general formula of alkynes is:', options:['CₙH₂ₙ','CₙH₂ₙ₊₂','CₙH₂ₙ₋₂','CₙH₃ₙ'], answer:2, explain:'Triple bond → two fewer H₂ than alkanes.'},
{q:'In fractional distillation, petrol is collected:', options:['At the bottom','Above kerosene','Below diesel','With bitumen'], answer:1, explain:'Lower boiling → higher in the tower: gas > petrol > kerosene > diesel.'},
{q:'Alkanes mainly undergo:', options:['Addition','Substitution','Polymerisation','Elimination'], answer:1, explain:'Saturated alkanes substitute H with Cl in sunlight.'},
{q:'Bitumen is used for:', options:['Jet fuel','Road surfacing','Cooking gas','Lubricants'], answer:1, explain:'The heaviest residue paves roads.'}
]},
{id:'kpk-c10-che-ch13', title:'Biochemistry', urdu:'حیاتیاتی کیمسٹری', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch13-l1', title:'Carbohydrates', html:'<h3>Classification</h3><ul><li><strong>Monosaccharides</strong> (simple sugars): <strong>glucose, fructose</strong> — C₆H₁₂O₆.</li><li><strong>Disaccharides:</strong> <strong>sucrose</strong> (table sugar), <strong>maltose, lactose</strong> — C₁₂H₂₂O₁₁.</li><li><strong>Polysaccharides:</strong> <strong>starch</strong> (energy storage in plants), <strong>glycogen</strong> (animals), <strong>cellulose</strong> (plant walls, fibre).</li></ul><p>Carbohydrates are the body’s <strong>primary energy source</strong>.</p>'},
{id:'kpk-c10-che-ch13-l2', title:'Proteins, Lipids and Nucleic Acids', html:'<h3>Proteins</h3><p>Made of <strong>amino acids</strong> joined by <strong>peptide bonds</strong>. Functions: enzymes, muscles, antibodies, hormones (insulin).</p><h3>Lipids</h3><p><strong>Fatty acids + glycerol</strong> → fats/oils. Concentrated energy, insulation, cell membranes.</p><h3>Nucleic Acids</h3><p><strong>DNA</strong> (double helix) stores genetic code; <strong>RNA</strong> helps make proteins. A <strong>nucleotide</strong> = sugar + phosphate + nitrogenous base (<strong>A, T, G, C</strong> in DNA; <strong>U</strong> replaces T in RNA).</p>'},
{id:'kpk-c10-che-ch13-l3', title:'Vitamins and Minerals', html:'<h3>Vitamins</h3><ul><li><strong>Fat-soluble:</strong> A (eyesight — lack → night blindness), D (bones — lack → rickets), E, K (blood clotting).</li><li><strong>Water-soluble:</strong> B-complex (B1 → beriberi), C (lack → scurvy).</li></ul><h3>Minerals</h3><p><strong>Calcium</strong> (bones/teeth), <strong>iron</strong> (haemoglobin — lack → anaemia), <strong>iodine</strong> (thyroid — lack → goitre), phosphorus, zinc.</p>'}],
quiz:[
{q:'Glucose is a:', options:['Disaccharide','Monosaccharide','Polysaccharide','Protein'], answer:1, explain:'A single sugar unit, C₆H₁₂O₆.'},
{q:'Table sugar (sucrose) is a:', options:['Monosaccharide','Disaccharide','Polysaccharide','Lipid'], answer:1, explain:'Glucose + fructose = C₁₂H₂₂O₁₁.'},
{q:'Starch is stored in:', options:['Animals','Plants','Bacteria','Fungi only'], answer:1, explain:'Plants store glucose as starch; animals use glycogen.'},
{q:'Proteins are made of:', options:['Fatty acids','Amino acids','Glucose units','Nucleotides'], answer:1, explain:'Amino acids linked by peptide bonds.'},
{q:'A nucleotide consists of:', options:['Sugar + protein','Sugar + phosphate + nitrogenous base','Fatty acid + glycerol','Amino acids'], answer:1, explain:'The three-part building block of DNA/RNA.'},
{q:'In RNA, thymine is replaced by:', options:['Adenine','Uracil','Guanine','Cytosine'], answer:1, explain:'RNA bases: A, U, G, C.'},
{q:'Deficiency of vitamin D causes:', options:['Scurvy','Rickets','Night blindness','Beriberi'], answer:1, explain:'Vitamin D builds strong bones.'},
{q:'Goitre is caused by lack of:', options:['Iron','Iodine','Calcium','Zinc'], answer:1, explain:'Iodine is needed for thyroid hormones.'},
{q:'Cellulose in the diet provides:', options:['Energy','Dietary fibre','Protein','Vitamins'], answer:1, explain:'Humans cannot digest it, but it aids bowel movement.'},
{q:'Haemoglobin needs the mineral:', options:['Calcium','Iron','Iodine','Sodium'], answer:1, explain:'Iron carries oxygen in haemoglobin; lack causes anaemia.'}
]},
{id:'kpk-c10-che-ch14', title:'The Atmosphere', urdu:'کرہ ہوائی', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch14-l1', title:'Composition and Layers', html:'<h3>Composition of Air</h3><p><strong>Nitrogen 78%</strong>, <strong>oxygen 21%</strong>, argon ~0.9%, <strong>CO₂ ~0.04%</strong>, plus water vapour and traces.</p><h3>Layers</h3><ul><li><strong>Troposphere:</strong> weather happens here (up to ~12 km).</li><li><strong>Stratosphere:</strong> holds the <strong>ozone layer</strong> (blocks UV).</li><li><strong>Mesosphere, thermosphere, exosphere</strong> above.</li></ul>'},
{id:'kpk-c10-che-ch14-l2', title:'Air Pollution', html:'<h3>Pollutants</h3><ul><li><strong>CO:</strong> from vehicles — binds haemoglobin, poisonous.</li><li><strong>SO₂, NOx:</strong> from industry/vehicles — cause <strong>acid rain</strong> and breathing problems.</li><li><strong>Particulates/smoke:</strong> smog.</li></ul><h3>Acid Rain</h3><p>SO₂ and NOx dissolve in rain → sulphuric/nitric acids — damages buildings, crops and lakes.</p>'},
{id:'kpk-c10-che-ch14-l3', title:'Ozone Depletion and Global Warming', html:'<h3>Ozone Depletion</h3><p><strong>CFCs</strong> (old refrigerants/sprays) destroy ozone, letting harmful <strong>UV</strong> through — more skin cancer and crop damage. The <strong>Montreal Protocol</strong> phased CFCs out.</p><h3>Global Warming</h3><p><strong>Greenhouse gases</strong> (CO₂, CH₄, water vapour) trap heat — the <strong>greenhouse effect</strong>. Excess CO₂ from fossil fuels drives <strong>global warming</strong> and climate change.</p>'}],
quiz:[
{q:'The most abundant gas in air is:', options:['Oxygen','Nitrogen','Carbon dioxide','Argon'], answer:1, explain:'Nitrogen is ~78% of the atmosphere.'},
{q:'CO₂ makes up about ___ of air.', options:['21%','0.04%','78%','1%'], answer:1, explain:'A small but climatically crucial fraction.'},
{q:'Weather occurs in the:', options:['Stratosphere','Troposphere','Mesosphere','Exosphere'], answer:1, explain:'The lowest layer holds almost all weather.'},
{q:'The ozone layer is in the:', options:['Troposphere','Stratosphere','Mesosphere','Thermosphere'], answer:1, explain:'Ozone peaks in the stratosphere, blocking UV.'},
{q:'Carbon monoxide is dangerous because it:', options:['Smells bad','Binds haemoglobin, blocking oxygen','Is acidic','Explodes'], answer:1, explain:'CO binds haemoglobin ~200× more strongly than O₂.'},
{q:'Acid rain is mainly caused by:', options:['CO₂ only','SO₂ and NOx','O₂','N₂'], answer:1, explain:'They form sulphuric and nitric acids in rain.'},
{q:'Ozone depletion is caused by:', options:['Oxygen','CFCs','Nitrogen','Water vapour'], answer:1, explain:'Chlorine from CFCs destroys ozone molecules.'},
{q:'The Montreal Protocol aimed to:', options:['Cut CO₂','Phase out CFCs','Ban cars','Stop acid rain'], answer:1, explain:'The 1987 treaty healed the ozone hole.'},
{q:'Which is a greenhouse gas?', options:['Oxygen','Methane','Nitrogen','Argon'], answer:1, explain:'CH₄, CO₂ and water vapour trap heat.'},
{q:'Global warming is driven mainly by excess:', options:['Oxygen','Carbon dioxide','Nitrogen','Helium'], answer:1, explain:'Fossil-fuel CO₂ enhances the greenhouse effect.'}
]},
{id:'kpk-c10-che-ch15', title:'Water', urdu:'پانی', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch15-l1', title:'Properties and Hardness', html:'<h3>Properties</h3><p>Water is the <strong>universal solvent</strong>; high specific heat, expands on freezing (ice floats), and shows <strong>capillary action</strong>.</p><h3>Hard vs Soft Water</h3><p><strong>Hard water</strong> contains Ca²⁺/Mg²⁺ salts — soap forms <strong>scum</strong> instead of lather.</p><ul><li><strong>Temporary hardness:</strong> bicarbonates — removed by <strong>boiling</strong>.</li><li><strong>Permanent hardness:</strong> sulphates/chlorides — removed by <strong>washing soda</strong> or ion exchange.</li></ul>'},
{id:'kpk-c10-che-ch15-l2', title:'Disadvantages of Hard Water', html:'<h3>Problems</h3><ul><li>Wastes soap (scum formation).</li><li><strong>Scales</strong> boilers and kettles — wasting fuel and risking bursts.</li><li>Spots on clothes and utensils.</li></ul><h3>Softening</h3><p>Boiling (temporary), washing soda Na₂CO₃ (permanent), and <strong>ion-exchange</strong> resins swap Ca²⁺/Mg²⁺ for Na⁺.</p>'},
{id:'kpk-c10-che-ch15-l3', title:'Water Pollution and Purification', html:'<h3>Pollution</h3><p>Sewage, industrial waste, fertilisers and pesticides pollute water. <strong>Waterborne diseases:</strong> <strong>cholera, typhoid, dysentery, hepatitis A</strong>.</p><h3>Purification</h3><ul><li><strong>Filtration</strong> removes suspended particles.</li><li><strong>Chlorination</strong> kills germs.</li><li><strong>Boiling</strong> kills germs at home.</li></ul><p>Save water: fix leaks, avoid waste — water is life.</p>'}],
quiz:[
{q:'Water is called the universal solvent because it:', options:['Is tasteless','Dissolves many substances','Is blue','Boils at 100°C'], answer:1, explain:'Its polarity dissolves ionic and many molecular substances.'},
{q:'Hard water contains salts of:', options:['Na⁺ and K⁺','Ca²⁺ and Mg²⁺','Al³⁺ only','NH₄⁺'], answer:1, explain:'Calcium and magnesium ions cause hardness.'},
{q:'Temporary hardness is due to:', options:['Sulphates','Bicarbonates','Chlorides','Nitrates'], answer:1, explain:'Ca(HCO₃)₂ and Mg(HCO₃)₂ — removed by boiling.'},
{q:'Permanent hardness is removed by:', options:['Boiling','Washing soda','Filtration','Cooling'], answer:1, explain:'Na₂CO₃ precipitates Ca²⁺/Mg²⁺ as carbonates.'},
{q:'Hard water wastes soap because it forms:', options:['Lather','Scum','Foam','Bubbles'], answer:1, explain:'Ca/Mg stearates precipitate as scum.'},
{q:'Boiler scale is dangerous because it:', options:['Tastes bad','Wastes fuel and can burst boilers','Softens water','Kills germs'], answer:1, explain:'Scale insulates heat transfer, overheating metal.'},
{q:'Which is a waterborne disease?', options:['Malaria','Typhoid','Tuberculosis','Measles'], answer:1, explain:'Typhoid spreads through contaminated water.'},
{q:'Chlorination of water is done to:', options:['Remove hardness','Kill germs','Add taste','Soften'], answer:1, explain:'Chlorine disinfects drinking water.'},
{q:'Ice floats on water because:', options:['It is warm','It is less dense than liquid water','Of surface tension','It contains air'], answer:1, explain:'Water’s anomalous expansion makes ice (0.917 g/cm³) float.'},
{q:'Ion-exchange softening swaps Ca²⁺/Mg²⁺ for:', options:['H⁺','Na⁺','Cl⁻','O²⁻'], answer:1, explain:'Resins release harmless Na⁺ in exchange.'}
]},
{id:'kpk-c10-che-ch16', title:'Chemical Industries', urdu:'کیمیائی صنعتیں', comingSoon:false, lessons:[
{id:'kpk-c10-che-ch16-l1', title:'Metallurgy', html:'<h3>Basic Operations</h3><ul><li><strong>Concentration:</strong> removing gangue (impurities) from ore.</li><li><strong>Roasting:</strong> heating sulphide ores in air (→ oxides).</li><li><strong>Smelting:</strong> reducing oxides with carbon/coke in a furnace.</li><li><strong>Refining:</strong> purifying the metal (e.g. electrolytic refining of copper).</li></ul><p>Reactive metals (Na, Al) are extracted by <strong>electrolysis</strong>; less reactive ones by carbon reduction.</p>'},
{id:'kpk-c10-che-ch16-l2', title:'Solvay Process — Sodium Carbonate', html:'<h3>Raw Materials</h3><p>Brine (NaCl), ammonia, limestone (CaCO₃ → CO₂ + CaO).</p><h3>Steps</h3><ol><li><strong>Ammonical brine</strong> preparation.</li><li><strong>Carbonation:</strong> CO₂ passed in → NaHCO₃ precipitates: NaCl + NH₃ + CO₂ + H₂O → NaHCO₃ + NH₄Cl.</li><li><strong>Filtration</strong> of NaHCO₃.</li><li><strong>Heating:</strong> 2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O.</li><li><strong>Ammonia recovery</strong> from NH₄Cl with slaked lime.</li></ol><p>Na₂CO₃ is used in glass, soap and paper.</p>'},
{id:'kpk-c10-che-ch16-l3', title:'Urea and Petroleum Industry', html:'<h3>Urea Manufacture</h3><p>Ammonia + carbon dioxide under pressure:</p><blockquote>2NH₃ + CO₂ → NH₂CONH₂ + H₂O</blockquote><p><strong>Urea</strong> (46% nitrogen) is Pakistan’s main nitrogenous fertiliser.</p><h3>Petroleum</h3><p>Refined into fuels and <strong>petrochemicals</strong> — plastics, detergents, synthetic fibres. Pakistan’s refineries (e.g. at Karachi) meet much of the fuel demand.</p>'}],
quiz:[
{q:'Roasting is:', options:['Heating ore in air','Melting metal','Dissolving ore','Cooling metal'], answer:0, explain:'Sulphide ores are roasted to oxides before reduction.'},
{q:'Smelting uses ___ to reduce metal oxides.', options:['Water','Carbon/coke','Oxygen','Acid'], answer:1, explain:'Coke reduces oxides in the blast furnace.'},
{q:'Highly reactive metals like aluminium are extracted by:', options:['Carbon reduction','Electrolysis','Roasting','Smelting'], answer:1, explain:'Carbon cannot reduce them; electricity does.'},
{q:'The raw materials of the Solvay process are:', options:['NaCl, NH₃, CaCO₃','Fe, C, O₂','N₂, H₂, Fe','Cu, Zn, C'], answer:0, explain:'Brine, ammonia and limestone.'},
{q:'In the Solvay process, the precipitate filtered off is:', options:['Na₂CO₃','NaHCO₃','NH₄Cl','CaCl₂'], answer:1, explain:'Sodium bicarbonate is sparingly soluble and precipitates.'},
{q:'Heating NaHCO₃ gives:', options:['NaCl','Na₂CO₃ + CO₂ + H₂O','NaOH','Na₂O'], answer:1, explain:'2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O.'},
{q:'Urea contains about ___ nitrogen.', options:['20%','46%','75%','10%'], answer:1, explain:'NH₂CONH₂ is 46% N — a rich fertiliser.'},
{q:'Urea is manufactured from:', options:['N₂ + H₂','NH₃ + CO₂','CH₄ + O₂','NaCl + H₂O'], answer:1, explain:'2NH₃ + CO₂ → urea + water under pressure.'},
{q:'Electrolytic refining gives:', options:['Ores','Very pure metals','Alloys','Slag'], answer:1, explain:'Impurities fall as anode mud; pure metal deposits on the cathode.'},
{q:'Petrochemicals include:', options:['Only fuels','Plastics, detergents, synthetic fibres','Metals','Cement'], answer:1, explain:'Petroleum feeds a huge chemical industry beyond fuel.'}
]}
]});

/* ============ KP BOARD — CLASS 10 BIOLOGY ============ */
window.__saMergeCourse({id:'kpk-class10-biology', board:'kp', title:'Biology', urdu:'حیاتیات', class:'Class 10', icon:'🧬', desc:'KP Board Class 10 Biology — full syllabus with lessons and quizzes.', chapters:[
{id:'kpk-c10-bio-ch1', title:'Gaseous Exchange', urdu:'گیسی تبادلہ', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch1-l1', title:'The Breathing System', html:'<h3>Air Passage</h3><p>Inhaled air travels: <strong>nasal cavity → pharynx → larynx → trachea → bronchi → bronchioles → alveoli</strong>. The trachea is held open by <strong>C-shaped cartilage rings</strong>; mucus and cilia trap dust.</p><h3>Alveoli</h3><p>Millions of tiny air sacs with <strong>thin walls, rich capillaries and huge surface area</strong> — ideal for diffusion: O₂ into blood, CO₂ out.</p>'},
{id:'kpk-c10-bio-ch1-l2', title:'Mechanism of Breathing', html:'<h3>Inhalation (active)</h3><ul><li>Ribs move <strong>up and out</strong> (intercostal muscles contract).</li><li><strong>Diaphragm contracts and flattens</strong>.</li><li>Chest volume rises → pressure falls → air rushes in.</li></ul><h3>Exhalation (passive)</h3><p>Muscles relax; ribs move down/in; diaphragm domes up; volume falls → air pushed out. Normal rate: <strong>15–18 breaths/min</strong>.</p>'},
{id:'kpk-c10-bio-ch1-l3', title:'Disorders and Smoking', html:'<h3>Respiratory Disorders</h3><ul><li><strong>Bronchitis:</strong> inflamed bronchi, persistent cough.</li><li><strong>Asthma:</strong> narrowed airways, wheezing — treated with inhalers.</li><li><strong>Emphysema:</strong> damaged alveoli (often from smoking).</li><li><strong>Pneumonia:</strong> infected, fluid-filled alveoli.</li></ul><h3>Smoking</h3><p>Tobacco smoke contains <strong>nicotine</strong> (addictive), <strong>tar</strong> (carcinogenic) and <strong>CO</strong> — causing lung cancer and heart disease. Plants exchange gases through <strong>stomata</strong> (leaves) and <strong>lenticels</strong> (stems).</p>'}],
quiz:[
{q:'The correct air passage order is:', options:['Trachea → nasal cavity → alveoli','Nasal cavity → trachea → bronchi → alveoli','Alveoli → bronchi → trachea','Pharynx → alveoli → bronchi'], answer:1, explain:'Air flows nose → pharynx → larynx → trachea → bronchi → bronchioles → alveoli.'},
{q:'Alveoli are adapted for gas exchange by having:', options:['Thick walls','Thin walls, capillaries, large surface area','No blood supply','Mucus coating'], answer:1, explain:'These three features maximise rapid diffusion.'},
{q:'During inhalation, the diaphragm:', options:['Relaxes and domes up','Contracts and flattens','Stops moving','Pushes ribs down'], answer:1, explain:'Flattening diaphragm enlarges the chest cavity.'},
{q:'Inhalation occurs when chest volume ___ and pressure ___.', options:['Rises, rises','Falls, falls','Rises, falls','Falls, rises'], answer:2, explain:'Larger volume → lower pressure → air flows in.'},
{q:'Normal breathing rate in adults is:', options:['5–8/min','15–18/min','40–50/min','100/min'], answer:1, explain:'About 15–18 breaths per minute at rest.'},
{q:'Asthma is characterised by:', options:['Fluid in alveoli','Narrowed airways and wheezing','Destroyed alveoli','Bacterial infection'], answer:1, explain:'Inflamed, constricted bronchioles cause wheezing.'},
{q:'The addictive substance in tobacco is:', options:['Tar','Nicotine','Carbon monoxide','Ash'], answer:1, explain:'Nicotine causes addiction; tar causes cancer.'},
{q:'Plants exchange gases mainly through:', options:['Roots only','Stomata in leaves','Flowers','Bark'], answer:1, explain:'Stomata open/close to regulate gas exchange and water loss.'},
{q:'Oxygen moves from alveoli into blood by:', options:['Active transport','Diffusion','Osmosis','Filtration'], answer:1, explain:'Down its concentration gradient into capillaries.'},
{q:'C-shaped cartilage in the trachea serves to:', options:['Filter air','Keep the airway open','Produce mucus','Warm the air'], answer:1, explain:'The rings prevent collapse during breathing.'}
]},
{id:'kpk-c10-bio-ch2', title:'Homeostasis', urdu:'ہومیوسٹیسس', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch2-l1', title:'What is Homeostasis?', html:'<h3>Definition</h3><p><strong>Homeostasis</strong> is keeping the <strong>internal environment constant</strong> despite external change — temperature, water, salts, glucose and pH.</p><h3>Examples</h3><ul><li><strong>Osmoregulation:</strong> balancing water and salts (kidneys).</li><li><strong>Thermoregulation:</strong> keeping body temperature ~37°C.</li></ul><p>Failure of homeostasis causes disease (e.g. diabetes from poor glucose control).</p>'},
{id:'kpk-c10-bio-ch2-l2', title:'The Kidney and Osmoregulation', html:'<h3>The Nephron</h3><p>Each kidney has ~1 million <strong>nephrons</strong>: <strong>glomerulus</strong> (knot of capillaries) inside <strong>Bowman’s capsule</strong>, leading to a long <strong>tubule</strong>.</p><h3>Urine Formation</h3><ol><li><strong>Filtration:</strong> water, salts, glucose, urea filter into the capsule.</li><li><strong>Reabsorption:</strong> all glucose, most water and salts return to blood.</li><li><strong>Secretion:</strong> extra wastes added.</li></ol><p>Result: <strong>urine</strong> (95% water, urea, salts). Kidney failure → <strong>dialysis</strong> (artificial filtration); <strong>kidney stones</strong> are crystallised salts.</p>'},
{id:'kpk-c10-bio-ch2-l3', title:'Thermoregulation and Plants', html:'<h3>Skin’s Role</h3><ul><li><strong>Hot:</strong> <strong>sweating</strong> (evaporation cools), <strong>vasodilation</strong> (more blood to skin).</li><li><strong>Cold:</strong> <strong>shivering</strong> (muscles make heat), <strong>vasoconstriction</strong>, hair erection (goosebumps).</li></ul><h3>Plants</h3><p>Plants regulate water via <strong>stomata</strong> (closing in drought), shed leaves in winter, and roll leaves to cut transpiration.</p>'}],
quiz:[
{q:'Homeostasis means:', options:['Rapid growth','Keeping internal conditions constant','Reproducing','Evolving'], answer:1, explain:'Stable temperature, water, salts and glucose despite outside change.'},
{q:'Osmoregulation is the balance of:', options:['Temperature','Water and salts','Glucose','Hormones'], answer:1, explain:'The kidneys regulate water and salt levels.'},
{q:'The functional unit of the kidney is the:', options:['Glomerulus alone','Nephron','Ureter','Bladder'], answer:1, explain:'Each nephron filters blood and forms urine.'},
{q:'In the nephron, filtration occurs at the:', options:['Loop of Henle','Glomerulus into Bowman’s capsule','Collecting duct','Ureter'], answer:1, explain:'High pressure forces fluid out of glomerular capillaries.'},
{q:'During reabsorption, the tubule takes back:', options:['Urea','All glucose and most water','Toxins','Excess salts only'], answer:1, explain:'Useful substances return to blood; urea stays.'},
{q:'Kidney failure patients need:', options:['Surgery always','Dialysis','More water only','No treatment'], answer:1, explain:'Dialysis artificially filters the blood.'},
{q:'In hot weather the skin:', options:['Vasoconstricts','Sweats and vasodilates','Shivers','Grows hair'], answer:1, explain:'Evaporation and extra skin blood flow dump heat.'},
{q:'Shivering helps in cold because:', options:['It looks warm','Muscle activity generates heat','It stops blood flow','It opens pores'], answer:1, explain:'Rapid contractions release heat.'},
{q:'Goosebumps are caused by:', options:['Sweat glands','Hair erector muscles','Fat cells','Nerves dying'], answer:1, explain:'Erector muscles raise hairs, trapping warm air.'},
{q:'Plants reduce water loss in drought by:', options:['Opening stomata','Closing stomata','Growing more leaves','Increasing transpiration'], answer:1, explain:'Closed stomata cut both gas exchange and water loss.'}
]},
{id:'kpk-c10-bio-ch3', title:'Coordination and Control', urdu:'رابطہ اور کنٹرول', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch3-l1', title:'The Nervous System', html:'<h3>Divisions</h3><ul><li><strong>CNS:</strong> brain + spinal cord — control centre.</li><li><strong>PNS:</strong> nerves linking body to CNS.</li></ul><h3>The Neuron</h3><p><strong>Dendrites</strong> receive signals → <strong>cell body</strong> → <strong>axon</strong> (insulated by <strong>myelin sheath</strong>) → <strong>synapse</strong> (chemical handover to the next neuron).</p><h3>Reflex Arc</h3><p>Receptor → sensory neuron → spinal cord → motor neuron → effector — e.g. jerking your hand from a hot object <strong>without</strong> waiting for the brain.</p>'},
{id:'kpk-c10-bio-ch3-l2', title:'Brain and Hormones', html:'<h3>Parts of the Brain</h3><ul><li><strong>Cerebrum:</strong> thought, memory, voluntary actions.</li><li><strong>Cerebellum:</strong> balance and coordination.</li><li><strong>Medulla:</strong> heartbeat, breathing (involuntary).</li></ul><h3>Endocrine Glands</h3><ul><li><strong>Pituitary</strong> (master gland) — growth hormone.</li><li><strong>Thyroid</strong> — thyroxine (metabolism; lack → goitre).</li><li><strong>Pancreas</strong> — <strong>insulin</strong> lowers blood glucose (lack → diabetes).</li><li><strong>Adrenal</strong> — <strong>adrenaline</strong> for emergencies (“fight or flight”).</li></ul>'},
{id:'kpk-c10-bio-ch3-l3', title:'Nervous vs Hormonal Control and Plant Hormones', html:'<h3>Comparison</h3><table><tr><th></th><th>Nervous</th><th>Hormonal</th></tr><tr><td>Speed</td><td>Very fast</td><td>Slow</td></tr><tr><td>Duration</td><td>Short-lived</td><td>Long-lasting</td></tr><tr><td>Path</td><td>Neurons</td><td>Blood</td></tr></table><h3>Plant Hormones</h3><ul><li><strong>Auxins:</strong> cell elongation, phototropism (bending to light).</li><li><strong>Gibberellins:</strong> stem growth, seed germination.</li></ul>'}],
quiz:[
{q:'The CNS consists of the:', options:['Nerves and receptors','Brain and spinal cord','Glands and hormones','Muscles and bones'], answer:1, explain:'Central = brain + spinal cord.'},
{q:'In a neuron, signals pass in the order:', options:['Axon → dendrites → cell body','Dendrites → cell body → axon','Synapse → axon → dendrites','Cell body → synapse → dendrites'], answer:1, explain:'Dendrites receive, the axon transmits.'},
{q:'The myelin sheath serves to:', options:['Receive signals','Speed up impulse transmission','Make hormones','Store energy'], answer:1, explain:'Insulation lets impulses jump rapidly along the axon.'},
{q:'A reflex arc bypasses the:', options:['Spinal cord','Brain','Receptor','Effector'], answer:1, explain:'The spinal cord handles it directly for speed.'},
{q:'Balance and coordination are controlled by the:', options:['Cerebrum','Cerebellum','Medulla','Hypothalamus'], answer:1, explain:'The “little brain” fine-tunes movement.'},
{q:'The master gland is the:', options:['Thyroid','Pituitary','Adrenal','Pancreas'], answer:1, explain:'Pituitary hormones control other glands.'},
{q:'Lack of insulin causes:', options:['Goitre','Diabetes','Cretinism','Addison’s disease'], answer:1, explain:'Without insulin, blood glucose stays high.'},
{q:'Adrenaline is released during:', options:['Sleep','Emergencies (fight or flight)','Digestion','Rest'], answer:1, explain:'It readies the body for action.'},
{q:'Compared to nervous control, hormonal control is:', options:['Faster','Slower but longer-lasting','Instant','Electrical'], answer:1, explain:'Hormones travel in blood — slow but persistent.'},
{q:'Phototropism (bending towards light) is controlled by:', options:['Gibberellins','Auxins','Insulin','Thyroxine'], answer:1, explain:'Auxins collect on the shaded side, elongating those cells.'}
]},
{id:'kpk-c10-bio-ch4', title:'Support and Movement', urdu:'سہارا اور حرکت', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch4-l1', title:'The Human Skeleton', html:'<h3>Functions</h3><p><strong>Support, protection</strong> (skull → brain, ribs → heart/lungs), <strong>movement</strong> (muscle anchors), <strong>blood-cell production</strong> (red marrow) and <strong>mineral storage</strong>.</p><h3>Bone Structure</h3><p><strong>Compact bone</strong> (hard outer), <strong>spongy bone</strong> (light inner), <strong>marrow</strong> (makes blood cells). <strong>Cartilage</strong> is flexible — at joint ends, nose and ears. Adults have <strong>206 bones</strong>.</p>'},
{id:'kpk-c10-bio-ch4-l2', title:'Joints and Muscles', html:'<h3>Joints</h3><ul><li><strong>Fixed:</strong> skull — no movement.</li><li><strong>Hinge:</strong> elbow, knee — back-and-forth.</li><li><strong>Ball-and-socket:</strong> shoulder, hip — all directions.</li></ul><p><strong>Ligaments</strong> join bone to bone; <strong>tendons</strong> join muscle to bone.</p><h3>Muscles</h3><p><strong>Skeletal</strong> (voluntary), <strong>smooth</strong> (involuntary, e.g. gut), <strong>cardiac</strong> (heart — never tires). <strong>Antagonistic pairs</strong>: biceps contracts to bend the arm while triceps relaxes, and vice versa.</p>'},
{id:'kpk-c10-bio-ch4-l3', title:'Disorders and Plant Support', html:'<h3>Bone and Joint Disorders</h3><ul><li><strong>Arthritis:</strong> inflamed, painful joints.</li><li><strong>Osteoporosis:</strong> brittle bones from calcium loss (common in old age).</li><li><strong>Fracture:</strong> broken bone — set with plaster.</li></ul><h3>Support in Plants</h3><p><strong>Turgor pressure</strong> keeps soft stems upright; <strong>xylem/wood</strong> supports tall trees.</p>'}],
quiz:[
{q:'The skull protects the:', options:['Heart','Brain','Lungs','Kidneys'], answer:1, explain:'The cranium shields the brain.'},
{q:'Blood cells are made in the:', options:['Compact bone','Bone marrow','Cartilage','Periosteum'], answer:1, explain:'Red marrow produces red and white blood cells.'},
{q:'An adult human has ___ bones.', options:['106','206','306','406'], answer:1, explain:'Babies have ~300, fusing to 206 in adults.'},
{q:'The elbow joint is a:', options:['Ball-and-socket joint','Hinge joint','Fixed joint','Gliding joint'], answer:1, explain:'It moves back-and-forth like a door hinge.'},
{q:'Ligaments connect:', options:['Muscle to bone','Bone to bone','Muscle to muscle','Skin to bone'], answer:1, explain:'Tendons connect muscle to bone.'},
{q:'Biceps and triceps work as:', options:['Similar muscles','An antagonistic pair','Cardiac muscles','Smooth muscles'], answer:1, explain:'One contracts while the other relaxes.'},
{q:'Cardiac muscle is special because it:', options:['Tires quickly','Never tires','Is voluntary','Has no striations'], answer:1, explain:'It contracts rhythmically for a lifetime.'},
{q:'Osteoporosis is:', options:['Joint inflammation','Brittle bones from mineral loss','A fracture','Muscle wasting'], answer:1, explain:'Low calcium/vitamin D weakens bones.'},
{q:'Arthritis affects the:', options:['Bones only','Joints','Muscles only','Skin'], answer:1, explain:'Inflamed joints become painful and stiff.'},
{q:'Herbaceous plants stay upright mainly by:', options:['Wood','Turgor pressure','Roots pulling','Flowers'], answer:1, explain:'Water-filled cells press outward, stiffening stems.'}
]},
{id:'kpk-c10-bio-ch5', title:'Reproduction', urdu:'تولید', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch5-l1', title:'Asexual Reproduction', html:'<h3>One Parent, Identical Offspring</h3><ul><li><strong>Binary fission:</strong> <em>Amoeba</em>, bacteria split in two.</li><li><strong>Budding:</strong> <em>Hydra</em>, yeast grow a bud.</li><li><strong>Spore formation:</strong> fungi release spores.</li><li><strong>Vegetative propagation:</strong> runners, bulbs, <strong>cutting, grafting, layering</strong> — used for roses, sugarcane, mangoes.</li></ul><p>Fast and simple, but <strong>no variation</strong> — clones.</p>'},
{id:'kpk-c10-bio-ch5-l2', title:'Sexual Reproduction in Plants', html:'<h3>The Flower</h3><p><strong>Sepals</strong> (protect), <strong>petals</strong> (attract), <strong>stamens</strong> (male: anther + filament make pollen), <strong>carpel</strong> (female: stigma, style, ovary with ovules).</p><h3>Pollination and Fertilization</h3><p><strong>Pollination:</strong> pollen lands on stigma — <strong>self</strong> (same flower) or <strong>cross</strong> (different plant, by wind/insects). Then the pollen tube grows, <strong>fertilization</strong> forms a zygote → <strong>seed</strong>; the ovary becomes the <strong>fruit</strong>.</p>'},
{id:'kpk-c10-bio-ch5-l3', title:'Sexual Reproduction in Humans', html:'<h3>Gametes</h3><p><strong>Male:</strong> testes make <strong>sperms</strong>. <strong>Female:</strong> ovaries release <strong>ova</strong> (one roughly monthly).</p><h3>Fertilization and Development</h3><p>Fertilization in the <strong>oviduct</strong> forms a <strong>zygote</strong>, which implants in the <strong>uterus</strong>. The <strong>placenta</strong> feeds the embryo; after ~9 months the baby is born. Twins may be <strong>identical</strong> (one zygote splits) or <strong>fraternal</strong>.</p>'}],
quiz:[
{q:'Binary fission occurs in:', options:['Hydra','Amoeba','Yeast','Rose'], answer:1, explain:'Amoeba simply splits into two daughter cells.'},
{q:'Grafting is used to propagate:', options:['Bacteria','Mango and rose plants','Amoeba','Fungi'], answer:1, explain:'A scion is joined to a rootstock — vegetative propagation.'},
{q:'The main disadvantage of asexual reproduction is:', options:['It is slow','No genetic variation','Needs two parents','Makes seeds'], answer:1, explain:'Clones cannot adapt to new diseases or climates.'},
{q:'Pollen is produced in the:', options:['Ovary','Anther','Stigma','Style'], answer:1, explain:'The anther (on the filament) makes pollen grains.'},
{q:'The female part of the flower is the:', options:['Stamen','Carpel','Petal','Sepal'], answer:1, explain:'Carpel = stigma + style + ovary.'},
{q:'Cross-pollination is carried out by:', options:['Roots','Wind and insects','Stems','Soil'], answer:1, explain:'Agents carry pollen between different plants, increasing variation.'},
{q:'After fertilization, the ovary becomes the:', options:['Seed','Fruit','Flower','Embryo'], answer:1, explain:'Ovules → seeds; ovary wall → fruit.'},
{q:'Human fertilization occurs in the:', options:['Uterus','Oviduct','Ovary','Vagina'], answer:1, explain:'Sperm meets ovum in the fallopian tube (oviduct).'},
{q:'The placenta’s function is to:', options:['Make sperms','Nourish the embryo','Produce ova','Pump blood'], answer:1, explain:'It transfers nutrients, oxygen and wastes between mother and fetus.'},
{q:'Identical twins come from:', options:['Two ova','One zygote splitting','Two sperms','Cloning'], answer:1, explain:'One fertilized egg divides into two embryos — same genes.'}
]},
{id:'kpk-c10-bio-ch6', title:'Inheritance', urdu:'وراثت', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch6-l1', title:'Mendel’s Experiments', html:'<h3>The Father of Genetics</h3><p><strong>Gregor Mendel</strong> crossed pea plants and tracked traits (tall/dwarf, round/wrinkled).</p><h3>Key Terms</h3><ul><li><strong>Gene:</strong> unit of heredity (DNA segment).</li><li><strong>Alleles:</strong> alternate forms (T/t).</li><li><strong>Dominant</strong> (T) masks <strong>recessive</strong> (t).</li><li><strong>Genotype:</strong> genetic makeup (Tt); <strong>phenotype:</strong> appearance (tall).</li><li><strong>Homozygous</strong> (TT/tt); <strong>heterozygous</strong> (Tt).</li></ul>'},
{id:'kpk-c10-bio-ch6-l2', title:'Monohybrid and Dihybrid Crosses', html:'<h3>Monohybrid Cross</h3><p>Tt × Tt → <strong>genotype 1:2:1</strong>, <strong>phenotype 3:1</strong> (3 tall : 1 dwarf). Mendel’s <strong>law of segregation</strong>: alleles separate into gametes.</p><h3>Dihybrid Cross</h3><p>Two traits together give <strong>9:3:3:1</strong> — Mendel’s <strong>law of independent assortment</strong>.</p><h3>Test Cross</h3><p>Crossing with a homozygous recessive (tt) reveals an unknown genotype.</p>'},
{id:'kpk-c10-bio-ch6-l3', title:'Chromosomes, Sex Determination and Variation', html:'<h3>Chromosomes</h3><p>Humans have <strong>46 chromosomes (23 pairs)</strong>: 22 autosome pairs + 1 sex pair. <strong>XX = female, XY = male</strong> — the father’s sperm decides the child’s sex.</p><h3>Variation</h3><ul><li><strong>Continuous</strong> (height, weight) — many genes.</li><li><strong>Discontinuous</strong> (blood group, tongue rolling) — single genes.</li></ul><p><strong>Mutations</strong> — sudden DNA changes — create new variations; most are harmful.</p>'}],
quiz:[
{q:'The father of genetics is:', options:['Darwin','Mendel','Lamarck','Watson'], answer:1, explain:'Mendel’s pea experiments founded genetics.'},
{q:'A heterozygous genotype is:', options:['TT','tt','Tt','tT²'], answer:2, explain:'Two different alleles: Tt.'},
{q:'The phenotype of Tt (T = tall dominant) is:', options:['Dwarf','Tall','Medium','Unknown'], answer:1, explain:'Dominant T masks recessive t.'},
{q:'A Tt × Tt cross gives phenotypic ratio:', options:['1:1','1:2:1','3:1','9:3:3:1'], answer:2, explain:'3 tall : 1 dwarf.'},
{q:'The law of segregation states that:', options:['Genes never separate','Alleles separate into different gametes','Traits blend','Only mothers pass genes'], answer:1, explain:'Each gamete gets one allele of each gene.'},
{q:'A dihybrid cross gives phenotypic ratio:', options:['3:1','1:2:1','9:3:3:1','1:1'], answer:2, explain:'Independent assortment of two traits.'},
{q:'Humans have ___ chromosomes.', options:['23','44','46','48'], answer:2, explain:'23 pairs: 22 autosomes + 1 sex pair.'},
{q:'A child’s sex is determined by the:', options:['Mother’s ovum','Father’s sperm','Environment','Diet'], answer:1, explain:'X or Y from the father makes XX or XY.'},
{q:'Blood group is an example of ___ variation.', options:['Continuous','Discontinuous','Environmental','Acquired'], answer:1, explain:'Distinct categories controlled by single genes.'},
{q:'Mutations are:', options:['Always useful','Sudden DNA changes, usually harmful','Only in plants','Always silent'], answer:1, explain:'Most mutations damage function; rare ones help evolution.'}
]},
{id:'kpk-c10-bio-ch7', title:'Man and His Environment', urdu:'انسان اور اس کا ماحول', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch7-l1', title:'Ecology Basics', html:'<h3>Levels</h3><p><strong>Population</strong> (one species) → <strong>community</strong> (all species) → <strong>ecosystem</strong> (community + non-living environment).</p><h3>Factors</h3><ul><li><strong>Biotic:</strong> living — predators, competitors, food.</li><li><strong>Abiotic:</strong> non-living — light, temperature, water, soil, air.</li></ul>'},
{id:'kpk-c10-bio-ch7-l2', title:'Food Chains, Webs and Cycles', html:'<h3>Feeding Levels</h3><p><strong>Producers</strong> (plants) → <strong>primary consumers</strong> (herbivores) → <strong>secondary consumers</strong> (carnivores) → <strong>decomposers</strong> (bacteria/fungi). Interconnected chains form a <strong>food web</strong>. Only ~<strong>10% of energy</strong> passes to each next level.</p><h3>Cycles</h3><ul><li><strong>Carbon cycle:</strong> photosynthesis ↔ respiration/combustion.</li><li><strong>Nitrogen cycle:</strong> fixation (bacteria/lightning) → nitrification → assimilation → denitrification.</li></ul><h3>Symbiosis</h3><p><strong>Mutualism</strong> (both benefit: lichen), <strong>commensalism</strong> (one benefits), <strong>parasitism</strong> (one harmed: tapeworm).</p>'},
{id:'kpk-c10-bio-ch7-l3', title:'Pollution and Conservation', html:'<h3>Pollution</h3><ul><li><strong>Air:</strong> smoke, CO, SO₂ — smog, acid rain.</li><li><strong>Water:</strong> sewage, chemicals — kills aquatic life.</li><li><strong>Land:</strong> plastics, pesticides.</li></ul><h3>Conservation</h3><p>Protect habitats, plant trees, reduce-reuse-recycle, use clean energy. Pakistan’s national parks (e.g. <strong>Chitral Gol</strong>, Margalla Hills) protect endangered species like the <strong>markhor</strong> and <strong>snow leopard</strong>.</p>'}],
quiz:[
{q:'An ecosystem includes:', options:['Only plants','Community plus non-living environment','Only animals','Only soil'], answer:1, explain:'Living community + abiotic surroundings.'},
{q:'Light and temperature are ___ factors.', options:['Biotic','Abiotic','Trophic','Genetic'], answer:1, explain:'Non-living environmental factors.'},
{q:'In a food chain, plants are:', options:['Consumers','Producers','Decomposers','Predators'], answer:1, explain:'They produce food by photosynthesis.'},
{q:'About ___ of energy passes to the next trophic level.', options:['100%','50%','10%','1%'], answer:2, explain:'Most energy is lost as heat — the 10% rule.'},
{q:'Decomposers include:', options:['Lions','Bacteria and fungi','Grass','Deer'], answer:1, explain:'They break down dead matter, recycling nutrients.'},
{q:'Nitrogen fixation is carried out by:', options:['Plants directly','Bacteria and lightning','Animals','Fungi only'], answer:1, explain:'They convert N₂ into usable compounds.'},
{q:'Lichen is an example of:', options:['Parasitism','Mutualism','Commensalism','Competition'], answer:1, explain:'Fungus + alga both benefit.'},
{q:'A tapeworm in the intestine shows:', options:['Mutualism','Commensalism','Parasitism','Symbiosis only'], answer:2, explain:'The worm benefits; the host is harmed.'},
{q:'Acid rain is mainly caused by:', options:['CO₂','SO₂ and NOx','O₂','Dust'], answer:1, explain:'They form acids in rainwater.'},
{q:'Chitral Gol National Park protects the:', options:['Lion','Markhor','Elephant','Panda'], answer:1, explain:'It is famous for the markhor, Pakistan’s national animal.'}
]},
{id:'kpk-c10-bio-ch8', title:'Biotechnology', urdu:'بائیوٹیکنالوجی', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch8-l1', title:'What is Biotechnology?', html:'<h3>Definition</h3><p><strong>Biotechnology</strong> uses living organisms or their products to make useful things — from ancient bread-making to modern gene editing.</p><h3>Fermentation</h3><p>Microbes at work: <strong>yeast</strong> → bread and alcohol; <strong>bacteria</strong> → yogurt, cheese; <strong>biogas</strong> from dung.</p>'},
{id:'kpk-c10-bio-ch8-l2', title:'Genetic Engineering', html:'<h3>Recombinant DNA</h3><p>Scientists cut a useful gene (e.g. human <strong>insulin</strong> gene) and paste it into bacteria, which then mass-produce the protein — pure, cheap insulin for diabetics.</p><h3>Achievements</h3><ul><li><strong>Medicine:</strong> insulin, vaccines, gene therapy.</li><li><strong>Agriculture:</strong> <strong>Bt cotton</strong> resists bollworms; virus-resistant crops.</li><li><strong>Environment:</strong> oil-eating bacteria clean spills.</li></ul>'},
{id:'kpk-c10-bio-ch8-l3', title:'Single-Cell Protein and Ethics', html:'<h3>Single-Cell Protein</h3><p>Dried microbial cells (<strong>yeast, algae like Spirulina</strong>) as protein-rich food/feed — fast to grow, needs little land.</p><h3>Concerns</h3><p>Safety testing of GM foods, <strong>bioweapons</strong> misuse, and patenting of life raise ethical questions needing laws and care.</p>'}],
quiz:[
{q:'Biotechnology is:', options:['Study of rocks','Using living organisms to make useful products','Making computers','Mining'], answer:1, explain:'From fermentation to genetic engineering.'},
{q:'Yeast fermentation is used in:', options:['Steel making','Bread and alcohol production','Paper making','Glass blowing'], answer:1, explain:'Yeast’s CO₂ raises dough; its ethanol makes drinks.'},
{q:'Genetic engineering of bacteria produces human insulin by:', options:['Prayer','Inserting the insulin gene into bacteria','Feeding them sugar','Heating them'], answer:1, explain:'Recombinant DNA makes bacteria insulin factories.'},
{q:'Bt cotton is special because it:', options:['Grows faster','Resists bollworm insects','Needs no water','Is colourful'], answer:1, explain:'A bacterial gene makes it pest-resistant.'},
{q:'Single-cell protein comes from:', options:['Cows','Yeast and algae','Wheat','Fish'], answer:1, explain:'Dried microbes like Spirulina are protein-rich.'},
{q:'Oil spills can be cleaned using:', options:['Fire only','Oil-eating bacteria','Sand only','Soap'], answer:1, explain:'Bioremediation by engineered microbes.'},
{q:'A concern about biotechnology is:', options:['It is too slow','Misuse and safety of GM organisms','It needs no labs','It is free'], answer:1, explain:'Ethics, testing and regulation matter.'},
{q:'Gene therapy aims to:', options:['Change eye colour','Treat disease by correcting genes','Make clones','Grow taller'], answer:1, explain:'Faulty genes are repaired or replaced.'},
{q:'Biogas is produced from:', options:['Coal','Animal dung by bacteria','Petrol','Wood'], answer:1, explain:'Anaerobic digestion gives methane fuel.'},
{q:'Vaccines are a product of biotechnology used in:', options:['Farming','Medicine','Mining','Textiles'], answer:1, explain:'They train immunity against disease.'}
]},
{id:'kpk-c10-bio-ch9', title:'Pharmacology', urdu:'فارماکولوجی', comingSoon:false, lessons:[
{id:'kpk-c10-bio-ch9-l1', title:'Drugs in Medicine', html:'<h3>What is Pharmacology?</h3><p><strong>Pharmacology</strong> studies drugs — their uses, doses and effects.</p><h3>Useful Drugs</h3><ul><li><strong>Antibiotics</strong> (penicillin — discovered by <strong>Fleming</strong>): kill bacteria.</li><li><strong>Vaccines</strong> (Jenner — smallpox): prevent disease by building immunity.</li><li><strong>Analgesics</strong> (aspirin, paracetamol): relieve pain and fever.</li><li><strong>Antiseptics</strong> (Dettol): kill germs on skin.</li></ul>'},
{id:'kpk-c10-bio-ch9-l2', title:'Drug Abuse', html:'<h3>Addictive Drugs</h3><ul><li><strong>Narcotics:</strong> opium, morphine, <strong>heroin</strong> — deadly addiction.</li><li><strong>Cannabis</strong> (chars/bhang), <strong>cocaine</strong>.</li><li><strong>Alcohol and tobacco:</strong> legal but harmful — liver damage, cancer.</li></ul><h3>Effects</h3><p>Addiction destroys health, family and future; overdose can kill. <strong>Say no</strong> — the first dose is the trap.</p>'},
{id:'kpk-c10-bio-ch9-l3', title:'Prevention and Treatment', html:'<h3>Fighting Drug Abuse</h3><ul><li><strong>Awareness:</strong> schools, media and parents warn the youth.</li><li><strong>Law enforcement:</strong> ANF (Anti-Narcotics Force) fights trafficking in Pakistan.</li><li><strong>Rehabilitation:</strong> addicts need medical treatment and counselling, not hatred.</li></ul><p>A healthy life — sports, faith, good friends — is the best protection.</p>'}],
quiz:[
{q:'Pharmacology is the study of:', options:['Plants','Drugs and their effects','Insects','Rocks'], answer:1, explain:'Uses, doses and side effects of medicines.'},
{q:'Penicillin was discovered by:', options:['Jenner','Fleming','Pasteur','Koch'], answer:1, explain:'Fleming (1928) noticed mould killing bacteria.'},
{q:'Antibiotics are effective against:', options:['Viruses','Bacteria','Fungi only','Worms only'], answer:1, explain:'They target bacterial structures — useless against viruses.'},
{q:'The first vaccine (smallpox) was made by:', options:['Fleming','Jenner','Lister','Ross'], answer:1, explain:'Jenner (1796) used cowpox to protect against smallpox.'},
{q:'Paracetamol is an:', options:['Antibiotic','Analgesic','Vaccine','Antiseptic'], answer:1, explain:'It relieves pain and fever.'},
{q:'Heroin is a:', options:['Medicine','Deadly narcotic','Vaccine','Vitamin'], answer:1, explain:'A highly addictive opioid — illegal and lethal.'},
{q:'The most dangerous step with drugs is:', options:['The last dose','The first dose','Seeing them','Reading about them'], answer:1, explain:'Addiction often starts with one “trial”.'},
{q:'In Pakistan, drug trafficking is fought by the:', options:['Police only','ANF (Anti-Narcotics Force)','Army only','Nobody'], answer:1, explain:'The Anti-Narcotics Force leads this fight.'},
{q:'Addicts need:', options:['Hatred','Treatment and rehabilitation','Punishment only','Isolation forever'], answer:1, explain:'Medical care plus counselling helps recovery.'},
{q:'Vaccines work by:', options:['Killing germs directly','Building immunity before infection','Reducing fever','Cleaning wounds'], answer:1, explain:'They train the immune system to recognise the germ.'}
]}
]});

/* ============ KP BOARD — CLASS 10 MATHEMATICS ============ */
window.__saMergeCourse({id:'kpk-class10-mathematics', board:'kp', title:'Mathematics', urdu:'ریاضی', class:'Class 10', icon:'📐', desc:'KP Board Class 10 Mathematics — full syllabus with lessons and quizzes.', chapters:[
{id:'kpk-c10-mat-ch1', title:'Quadratic Equations', urdu:'دو درجی مساواتیں', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch1-l1', title:'Standard Form and Factorization', html:'<h3>Standard Form</h3><p>A <strong>quadratic equation</strong> is ax² + bx + c = 0 with <strong>a ≠ 0</strong>.</p><h3>Solving by Factorization</h3><p>Factorise and set each factor to zero: x² + 5x + 6 = 0 → (x+2)(x+3) = 0 → x = −2 or x = −3.</p><p><strong>Worked example:</strong> 2x² − 7x + 3 = 0 → (2x−1)(x−3) = 0 → x = 1/2 or x = 3.</p>'},
{id:'kpk-c10-mat-ch1-l2', title:'Completing the Square and the Formula', html:'<h3>Completing the Square</h3><p>x² + 6x + 5 = 0 → (x+3)² − 9 + 5 = 0 → (x+3)² = 4 → x+3 = ±2 → x = −1 or x = −5.</p><h3>Quadratic Formula</h3><blockquote>x = (−b ± √(b²−4ac)) / 2a</blockquote><p><strong>Worked example:</strong> x² − 4x + 2 = 0 → x = (4 ± √(16−8))/2 = (4 ± √8)/2 = 2 ± √2.</p>'},
{id:'kpk-c10-mat-ch1-l3', title:'Reducible Equations and Word Problems', html:'<h3>Reducible to Quadratic</h3><ul><li><strong>Biquadratic:</strong> x⁴ − 5x² + 4 = 0 → let y = x²: y² − 5y + 4 = 0 → y = 1, 4 → x = ±1, ±2.</li><li><strong>Radical:</strong> isolate and square, then <strong>check</strong> answers.</li></ul><h3>Word Problems</h3><p>Translate carefully: “the product of two consecutive integers is 56” → x(x+1) = 56 → x² + x − 56 = 0 → x = 7 (positive).</p>'}],
quiz:[
{q:'The standard form of a quadratic equation is:', options:['ax + b = 0','ax² + bx + c = 0, a ≠ 0','ax³ + b = 0','a/x + b = 0'], answer:1, explain:'Degree 2 with non-zero leading coefficient.'},
{q:'The solutions of x² + 5x + 6 = 0 are:', options:['x = 2, 3','x = −2, −3','x = 1, 6','x = −1, −6'], answer:1, explain:'(x+2)(x+3) = 0.'},
{q:'Solving 2x² − 7x + 3 = 0 gives:', options:['x = 3 or x = 1/2','x = −3 or x = −1/2','x = 7 or x = 3','x = 1 or x = 3/2'], answer:0, explain:'(2x−1)(x−3) = 0.'},
{q:'The quadratic formula is:', options:['x = (−b ± √(b²+4ac))/2a','x = (−b ± √(b²−4ac))/2a','x = (b ± √(b²−4ac))/2a','x = (−b ± √(b²−4ac))/a'], answer:1, explain:'Derived by completing the square on ax²+bx+c = 0.'},
{q:'Using the formula, x² − 4x + 2 = 0 gives:', options:['x = 2 ± √2','x = 4 ± √2','x = 2 ± √8','x = −2 ± √2'], answer:0, explain:'(4 ± √8)/2 = 2 ± √2.'},
{q:'Completing the square: x² + 6x + 5 = 0 gives:', options:['x = −1 or −5','x = 1 or 5','x = −2 or −3','x = −6 or 1'], answer:0, explain:'(x+3)² = 4 → x = −3 ± 2.'},
{q:'For x⁴ − 5x² + 4 = 0, substituting y = x² gives:', options:['y² − 5y + 4 = 0','y² + 5y + 4 = 0','y⁴ − 5y + 4 = 0','y² − 5y − 4 = 0'], answer:0, explain:'Biquadratic reduces to quadratic in y.'},
{q:'The roots of x⁴ − 5x² + 4 = 0 are:', options:['±1, ±4','±1, ±2','1, 4','−1, −4'], answer:1, explain:'y = 1 or 4, so x = ±1, ±2.'},
{q:'After squaring a radical equation, you must:', options:['Square again','Check the answers','Add 1','Do nothing'], answer:1, explain:'Squaring can introduce extraneous roots.'},
{q:'Two consecutive positive integers with product 56 are:', options:['6 and 8','7 and 8','5 and 6','8 and 9'], answer:1, explain:'x(x+1) = 56 → x = 7.'}
]},
{id:'kpk-c10-mat-ch2', title:'Theory of Quadratic Equations', urdu:'دو درجی مساواتوں کا نظریہ', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch2-l1', title:'The Discriminant', html:'<h3>Definition</h3><p>For ax² + bx + c = 0, the <strong>discriminant</strong> is:</p><blockquote>D = b² − 4ac</blockquote><h3>Nature of Roots</h3><ul><li><strong>D &gt; 0 and perfect square:</strong> rational, unequal.</li><li><strong>D &gt; 0, not perfect square:</strong> irrational, unequal.</li><li><strong>D = 0:</strong> equal, rational.</li><li><strong>D &lt; 0:</strong> imaginary (complex conjugate).</li></ul><p><strong>Worked example:</strong> x² − 6x + 9 = 0: D = 36 − 36 = 0 → equal roots (x = 3).</p>'},
{id:'kpk-c10-mat-ch2-l2', title:'Cube Roots of Unity', html:'<h3>Finding Them</h3><p>x³ = 1 → (x−1)(x²+x+1) = 0. Roots: <strong>1, ω, ω²</strong> where ω = (−1+√−3)/2.</p><h3>Properties</h3><blockquote>1 + ω + ω² = 0;   ω³ = 1</blockquote><p>Use these to simplify: (1+ω)² = 1 + 2ω + ω² = ω (since 1+ω² = −ω… check: = (1+ω+ω²) + ω = ω). These identities are exam favourites.</p>'},
{id:'kpk-c10-mat-ch2-l3', title:'Sum, Product and Symmetric Functions', html:'<h3>Relations</h3><p>If α, β are roots of ax² + bx + c = 0:</p><blockquote>α + β = −b/a;   αβ = c/a</blockquote><h3>Symmetric Functions</h3><p>α² + β² = (α+β)² − 2αβ. <strong>Worked example:</strong> roots of x² − 5x + 6 = 0 are 2, 3: sum = 5 = −(−5)/1 ✓, product = 6 ✓.</p><h3>Forming Equations</h3><p>With sum S and product P: x² − Sx + P = 0.</p>'}],
quiz:[
{q:'The discriminant of ax² + bx + c = 0 is:', options:['b² + 4ac','b² − 4ac','4ac − b²','√(b²−4ac)'], answer:1, explain:'D = b² − 4ac decides the nature of roots.'},
{q:'If D > 0 and a perfect square, roots are:', options:['Equal','Rational and unequal','Irrational','Imaginary'], answer:1, explain:'√D rational gives two distinct rational roots.'},
{q:'x² − 6x + 9 = 0 has roots that are:', options:['Irrational','Equal and rational','Imaginary','Unequal rational'], answer:1, explain:'D = 36 − 36 = 0.'},
{q:'D < 0 gives roots that are:', options:['Real and equal','Imaginary/complex','Rational','Zero'], answer:1, explain:'Negative under the root → complex conjugates.'},
{q:'The cube roots of unity are:', options:['1, −1, 0','1, ω, ω²','1, 2, 3','i, −i, 1'], answer:1, explain:'From (x−1)(x²+x+1) = 0.'},
{q:'1 + ω + ω² equals:', options:['1','0','3','ω³'], answer:1, explain:'The defining relation of complex cube roots of unity.'},
{q:'ω³ equals:', options:['0','1','−1','ω'], answer:1, explain:'Since ω³ = 1 by definition.'},
{q:'If α, β are roots of ax² + bx + c = 0, α + β equals:', options:['b/a','−b/a','c/a','−c/a'], answer:1, explain:'Sum of roots = −b/a.'},
{q:'For x² − 5x + 6 = 0, the product of roots is:', options:['5','−5','6','−6'], answer:2, explain:'αβ = c/a = 6.'},
{q:'An equation with roots 2 and 3 is:', options:['x² − 5x + 6 = 0','x² + 5x + 6 = 0','x² − 5x − 6 = 0','x² + 6x + 5 = 0'], answer:0, explain:'x² − Sx + P = x² − 5x + 6.'}
]},
{id:'kpk-c10-mat-ch3', title:'Variations', urdu:'تغیرات', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch3-l1', title:'Direct Variation', html:'<h3>Definition</h3><p><strong>y varies directly as x</strong> (y ∝ x) means:</p><blockquote>y = kx (k = constant)</blockquote><p>As x doubles, y doubles. Example: cost ∝ number of items.</p><p><strong>Worked example:</strong> y ∝ x, y = 12 when x = 3 → k = 4; when x = 5, y = 20.</p>'},
{id:'kpk-c10-mat-ch3-l2', title:'Inverse Variation', html:'<h3>Definition</h3><p><strong>y varies inversely as x</strong> (y ∝ 1/x) means:</p><blockquote>y = k/x, i.e. xy = k</blockquote><p>As x doubles, y halves. Example: speed ∝ 1/time for a fixed distance.</p><p><strong>Worked example:</strong> y ∝ 1/x, y = 6 when x = 4 → k = 24; when x = 8, y = 3.</p>'},
{id:'kpk-c10-mat-ch3-l3', title:'Joint and Combined Variation', html:'<h3>Joint Variation</h3><p><strong>y ∝ xz</strong> → y = kxz. Example: interest ∝ principal × time.</p><h3>Combined Variation</h3><p>Mix of direct and inverse: y ∝ x/z → y = kx/z.</p><p><strong>Worked example:</strong> y ∝ x² (y varies directly as the square of x): if y = 18 when x = 3, k = 2; when x = 5, y = 50.</p>'}],
quiz:[
{q:'If y ∝ x and y = 12 when x = 3, then y when x = 5 is:', options:['15','20','30','60'], answer:1, explain:'k = 12/3 = 4; y = 4 × 5 = 20.'},
{q:'Inverse variation is written as:', options:['y = kx','y = k/x','y = kx²','y = x + k'], answer:1, explain:'y ∝ 1/x.'},
{q:'If y ∝ 1/x, y = 6 when x = 4, then y when x = 8 is:', options:['12','3','24','48'], answer:1, explain:'k = xy = 24; y = 24/8 = 3.'},
{q:'Joint variation y ∝ xz means:', options:['y = k(x+z)','y = kxz','y = kx/z','y = k + xz'], answer:1, explain:'Joint = product of the variables.'},
{q:'Speed for a fixed distance varies ___ with time.', options:['Directly','Inversely','Jointly','Not at all'], answer:1, explain:'v = d/t: more time, less speed.'},
{q:'If y ∝ x², y = 18 when x = 3, then k equals:', options:['6','2','9','54'], answer:1, explain:'k = y/x² = 18/9 = 2.'},
{q:'With k = 2 in y = kx², y when x = 5 is:', options:['20','50','10','25'], answer:1, explain:'y = 2 × 25 = 50.'},
{q:'The constant k in y = kx is found by:', options:['k = xy','k = y/x','k = x + y','k = y − x'], answer:1, explain:'k = y/x from y = kx.'},
{q:'Combined variation y ∝ x/z is written:', options:['y = kxz','y = kx/z','y = kz/x','y = k(x+z)'], answer:1, explain:'Direct in x, inverse in z.'},
{q:'If workers ∝ 1/days for a fixed job, doubling workers:', options:['Doubles days','Halves days','Keeps days same','Triples days'], answer:1, explain:'Inverse: more workers, fewer days.'}
]},
{id:'kpk-c10-mat-ch4', title:'Partial Fractions', urdu:'جزوی کسور', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch4-l1', title:'Proper and Improper Fractions', html:'<h3>Definitions</h3><p>A rational fraction P(x)/Q(x):</p><ul><li><strong>Proper:</strong> degree of P &lt; degree of Q.</li><li><strong>Improper:</strong> degree of P ≥ degree of Q — divide first.</li></ul><p>Partial fractions split a proper fraction into simpler ones for integration and algebra.</p>'},
{id:'kpk-c10-mat-ch4-l2', title:'Linear Factors', html:'<h3>Distinct Linear Factors</h3><p>(3x+5)/((x+1)(x+2)) = A/(x+1) + B/(x+2). Multiply out: 3x+5 = A(x+2) + B(x+1). Set x = −1: 2 = A; x = −2: −1 = −B → B = 1. So = 2/(x+1) + 1/(x+2).</p><h3>Repeated Linear Factors</h3><p>For (x+1)²: use A/(x+1) + B/(x+1)².</p>'},
{id:'kpk-c10-mat-ch4-l3', title:'Quadratic Factors', html:'<h3>Irreducible Quadratic</h3><p>For a factor like x²+1 (cannot factorise over reals): use <strong>(Ax+B)/(x²+1)</strong>.</p><p><strong>Worked example:</strong> (2x+3)/((x+1)(x²+1)) = A/(x+1) + (Bx+C)/(x²+1). Solving: A = 1/2, B = 3/2, C = 5/2 — found by comparing coefficients.</p>'}],
quiz:[
{q:'A proper fraction has:', options:['Numerator degree > denominator degree','Numerator degree < denominator degree','Equal degrees','Zero denominator'], answer:1, explain:'Proper: deg P < deg Q.'},
{q:'Before resolving an improper fraction, you must:', options:['Factorise','Divide','Differentiate','Square it'], answer:1, explain:'Polynomial division first gives quotient + proper remainder fraction.'},
{q:'For distinct linear factors (x+1)(x+2), the form is:', options:['A/(x+1) + B/(x+2)','A/(x+1)² + B/(x+2)','(Ax+B)/(x+1) + C/(x+2)','A + B'], answer:0, explain:'One constant per distinct linear factor.'},
{q:'For a repeated factor (x+1)², the form includes:', options:['A/(x+1) only','A/(x+1) + B/(x+1)²','A/(x+1)² only','(Ax+B)/(x+1)'], answer:1, explain:'Powers 1 through n each get a term.'},
{q:'For an irreducible quadratic x²+1, the numerator is of the form:', options:['A','Ax + B','Ax² + B','A/x'], answer:1, explain:'One degree less than the quadratic: Ax + B.'},
{q:'x² + 1 is irreducible over the reals because:', options:['It has real roots','Its discriminant is negative','It is quadratic','It has no x term'], answer:1, explain:'D = 0 − 4 = −4 < 0: no real factors.'},
{q:'In the example, A for (3x+5)/((x+1)(x+2)) was found by setting:', options:['x = 0','x = −1','x = 1','x = −2 for A'], answer:1, explain:'x = −1 kills the B term, leaving 2 = A.'},
{q:'Partial fractions are mainly used to simplify:', options:['Addition','Integration and equations','Geometry','Statistics'], answer:1, explain:'They make integrals and inverse Laplace transforms easy.'},
{q:'(2x)/(x²−1) resolves with denominators:', options:['(x−1) and (x+1)','(x−1)²','(x²+1)','x and (x−1)'], answer:0, explain:'x² − 1 = (x−1)(x+1), distinct linear factors.'},
{q:'The number of constants for (x+1)(x+2)(x+3) is:', options:['1','2','3','6'], answer:2, explain:'One constant per distinct linear factor.'}
]},
{id:'kpk-c10-mat-ch5', title:'Sets and Functions', urdu:'سیٹ اور فنکشن', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch5-l1', title:'Sets and Operations', html:'<h3>Basics</h3><p>A <strong>set</strong> is a well-defined collection: A = {1, 2, 3}. <strong>∈</strong> means “is an element of”.</p><h3>Operations</h3><ul><li><strong>Union:</strong> A ∪ B (in either).</li><li><strong>Intersection:</strong> A ∩ B (in both).</li><li><strong>Difference:</strong> A − B (in A not B).</li><li><strong>Complement:</strong> A′ (not in A).</li></ul><p><strong>Worked example:</strong> A = {1,2,3}, B = {2,3,4}: A ∪ B = {1,2,3,4}, A ∩ B = {2,3}.</p>'},
{id:'kpk-c10-mat-ch5-l2', title:'Venn Diagrams and Laws', html:'<h3>De Morgan’s Laws</h3><blockquote>(A ∪ B)′ = A′ ∩ B′<br>(A ∩ B)′ = A′ ∪ B′</blockquote><h3>Number of Elements</h3><blockquote>n(A ∪ B) = n(A) + n(B) − n(A ∩ B)</blockquote><p><strong>Worked example:</strong> 30 students: 18 play cricket, 15 football, 8 both → cricket or football = 18 + 15 − 8 = 25.</p>'},
{id:'kpk-c10-mat-ch5-l3', title:'Relations and Functions', html:'<h3>Relation</h3><p>A <strong>relation</strong> is a set of ordered pairs. <strong>Domain</strong> = first elements; <strong>range</strong> = second elements.</p><h3>Function</h3><p>A <strong>function</strong> gives <strong>each domain element exactly one</strong> image. f(x) = 2x + 1: f(3) = 7.</p><h3>Types</h3><p><strong>One-one (injective):</strong> distinct inputs → distinct outputs. <strong>Onto (surjective):</strong> range = whole codomain. Both → <strong>bijective</strong>.</p>'}],
quiz:[
{q:'If A = {1,2,3} and B = {2,3,4}, A ∪ B is:', options:['{2,3}','{1,2,3,4}','{1,4}','{ }'], answer:1, explain:'Union collects all distinct elements.'},
{q:'For the same sets, A ∩ B is:', options:['{1,2,3,4}','{2,3}','{1,4}','{1,2}'], answer:1, explain:'Intersection keeps common elements.'},
{q:'De Morgan’s law: (A ∪ B)′ equals:', options:['A′ ∪ B′','A′ ∩ B′','A ∩ B','A ∪ B'], answer:1, explain:'Complement of union = intersection of complements.'},
{q:'n(A ∪ B) equals:', options:['n(A) + n(B)','n(A) + n(B) − n(A ∩ B)','n(A) × n(B)','n(A) − n(B)'], answer:1, explain:'Subtract the double-counted intersection.'},
{q:'18 play cricket, 15 football, 8 both (30 students). Playing at least one:', options:['33','25','23','41'], answer:1, explain:'18 + 15 − 8 = 25.'},
{q:'A relation is a function if each domain element has:', options:['At least two images','Exactly one image','No image','Infinite images'], answer:1, explain:'The defining property of a function.'},
{q:'If f(x) = 2x + 1, then f(3) is:', options:['6','7','5','9'], answer:1, explain:'2(3) + 1 = 7.'},
{q:'The domain of {(1,2),(3,4),(5,6)} is:', options:['{2,4,6}','{1,3,5}','{1,2,3}','{4,5,6}'], answer:1, explain:'Domain = set of first elements.'},
{q:'A function that is both one-one and onto is:', options:['Constant','Bijective','Many-one','Undefined'], answer:1, explain:'Bijective = injective + surjective.'},
{q:'The complement A′ contains elements:', options:['In A','Not in A (but in universal set)','In both A and B','Nowhere'], answer:1, explain:'Everything in U outside A.'}
]},
{id:'kpk-c10-mat-ch6', title:'Basic Statistics', urdu:'بنیادی شماریات', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch6-l1', title:'Data and Frequency Tables', html:'<h3>Data</h3><p><strong>Primary data</strong> is collected first-hand; <strong>secondary data</strong> comes from published sources.</p><h3>Frequency Distribution</h3><p>Group data into <strong>classes</strong> with <strong>tallies</strong>. Example — marks of 20 students grouped 0–10, 10–20, …; the <strong>modal class</strong> has the highest frequency.</p>'},
{id:'kpk-c10-mat-ch6-l2', title:'Mean, Median and Mode', html:'<h3>Measures of Central Tendency</h3><ul><li><strong>Mean:</strong> x̄ = Σx/n (ungrouped) or Σfx/Σf (grouped).</li><li><strong>Median:</strong> middle value of ordered data.</li><li><strong>Mode:</strong> most frequent value.</li></ul><p><strong>Worked example:</strong> 2, 4, 4, 5, 10: mean = 25/5 = 5; median = 4; mode = 4.</p>'},
{id:'kpk-c10-mat-ch6-l3', title:'Dispersion and Graphs', html:'<h3>Measures of Dispersion</h3><ul><li><strong>Range</strong> = max − min.</li><li><strong>Variance</strong> = average of squared deviations.</li><li><strong>Standard deviation</strong> = √variance.</li></ul><h3>Graphs</h3><p><strong>Histogram</strong> (bars touch for continuous data), <strong>frequency polygon</strong> (join midpoints), <strong>pie chart</strong> (angles = fraction × 360°).</p>'}],
quiz:[
{q:'Data collected first-hand is:', options:['Secondary data','Primary data','Grouped data','False data'], answer:1, explain:'Primary = original collection by the investigator.'},
{q:'The mean of 2, 4, 4, 5, 10 is:', options:['4','5','6','25'], answer:1, explain:'Sum 25 ÷ 5 = 5.'},
{q:'The median of 2, 4, 4, 5, 10 is:', options:['5','4','10','2'], answer:1, explain:'The middle (3rd) value of ordered data.'},
{q:'The mode of 2, 4, 4, 5, 10 is:', options:['5','2','4','10'], answer:2, explain:'4 occurs most often.'},
{q:'Range of the data 3, 7, 7, 12, 20 is:', options:['20','17','10','7'], answer:1, explain:'20 − 3 = 17.'},
{q:'Standard deviation is the square root of the:', options:['Mean','Variance','Range','Mode'], answer:1, explain:'SD = √variance.'},
{q:'In a pie chart, a 25% share gets angle:', options:['25°','90°','180°','360°'], answer:1, explain:'0.25 × 360° = 90°.'},
{q:'Histogram bars for continuous data:', options:['Are separated','Touch each other','Are circles','Have gaps always'], answer:1, explain:'Classes are continuous, so bars touch.'},
{q:'The modal class is the class with:', options:['Lowest frequency','Highest frequency','Widest range','Most classes'], answer:1, explain:'Mode = most frequent.'},
{q:'Mean of grouped data uses:', options:['Σx/n','Σfx/Σf','Middle value','Highest frequency'], answer:1, explain:'Weight each midpoint by its frequency.'}
]},
{id:'kpk-c10-mat-ch7', title:'Introduction to Trigonometry', urdu:'مثلثیات کا تعارف', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch7-l1', title:'Trigonometric Ratios', html:'<h3>The Six Ratios</h3><p>For acute angle θ in a right triangle (opposite, adjacent, hypotenuse):</p><blockquote>sin θ = opp/hyp;  cos θ = adj/hyp;  tan θ = opp/adj<br>cosec θ = 1/sin θ;  sec θ = 1/cos θ;  cot θ = 1/tan θ</blockquote><p><strong>Memory:</strong> SOH-CAH-TOA.</p><p><strong>Worked example:</strong> opp = 3, adj = 4, hyp = 5: sin θ = 3/5, cos θ = 4/5, tan θ = 3/4.</p>'},
{id:'kpk-c10-mat-ch7-l2', title:'Special Angles and Identities', html:'<h3>Standard Values</h3><table><tr><th>θ</th><th>0°</th><th>30°</th><th>45°</th><th>60°</th><th>90°</th></tr><tr><td>sin</td><td>0</td><td>1/2</td><td>1/√2</td><td>√3/2</td><td>1</td></tr><tr><td>cos</td><td>1</td><td>√3/2</td><td>1/√2</td><td>1/2</td><td>0</td></tr><tr><td>tan</td><td>0</td><td>1/√3</td><td>1</td><td>√3</td><td>undefined</td></tr></table><h3>Identities</h3><blockquote>sin²θ + cos²θ = 1<br>1 + tan²θ = sec²θ<br>1 + cot²θ = cosec²θ</blockquote>'},
{id:'kpk-c10-mat-ch7-l3', title:'Heights and Distances', html:'<h3>Angle of Elevation and Depression</h3><p><strong>Elevation:</strong> angle <em>up</em> from the horizontal to the object. <strong>Depression:</strong> angle <em>down</em> from the horizontal.</p><p><strong>Worked example:</strong> a 20 m tower; angle of elevation 45° → distance = 20/tan45° = 20 m.</p><p>Steps: draw the right triangle, label knowns, pick the ratio with the unknown, solve.</p>'}],
quiz:[
{q:'sin θ equals:', options:['adj/hyp','opp/hyp','opp/adj','hyp/opp'], answer:1, explain:'SOH: sine = opposite/hypotenuse.'},
{q:'tan 45° equals:', options:['0','1','√3','1/√3'], answer:1, explain:'In a 45° isosceles triangle, opp = adj.'},
{q:'sin 30° equals:', options:['√3/2','1/2','1/√2','1'], answer:1, explain:'Standard value.'},
{q:'The identity sin²θ + cos²θ equals:', options:['0','1','2','tan²θ'], answer:1, explain:'The fundamental Pythagorean identity.'},
{q:'1 + tan²θ equals:', options:['sin²θ','sec²θ','cosec²θ','cot²θ'], answer:1, explain:'Divide sin²+cos² = 1 by cos².'},
{q:'For opp = 3, adj = 4, hyp = 5: cos θ is:', options:['3/5','4/5','3/4','5/4'], answer:1, explain:'CAH: adjacent/hypotenuse.'},
{q:'The angle of depression is measured:', options:['Up from horizontal','Down from horizontal','From the object','Vertically'], answer:1, explain:'Depression looks downward from the horizontal.'},
{q:'A 20 m tower with 45° elevation stands ___ away.', options:['10 m','20 m','40 m','28.3 m'], answer:1, explain:'d = 20/tan45° = 20 m.'},
{q:'sec θ is the reciprocal of:', options:['sin θ','cos θ','tan θ','cot θ'], answer:1, explain:'sec = 1/cos.'},
{q:'tan 90° is:', options:['0','1','Undefined','−1'], answer:2, explain:'sin90/cos90 = 1/0 — undefined.'}
]},
{id:'kpk-c10-mat-ch8', title:'Projection of a Side of a Triangle', urdu:'مثلث کے ضلع کا پروجیکشن', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch8-l1', title:'What is Projection?', html:'<h3>Definition</h3><p>The <strong>projection</strong> of a segment onto a line is the segment between the feet of the perpendiculars from its ends. The projection of a side onto the base is found by dropping a perpendicular.</p><p>In ΔABC with altitude from B to base AC meeting at D: <strong>AD is the projection of AB</strong> on AC.</p>'},
{id:'kpk-c10-mat-ch8-l2', title:'Theorems', html:'<h3>Acute-Angle Theorem</h3><p><em>In an acute triangle, the square of the side opposite an acute angle equals the sum of the squares of the other two sides <strong>minus twice</strong> the product of one side and the projection of the other on it.</em></p><h3>Obtuse-Angle Theorem</h3><p><em>For the side opposite an obtuse angle, the same holds with <strong>plus twice</strong> the product.</em></p><p>Both are proved with Pythagoras on the two right triangles formed by the altitude.</p>'},
{id:'kpk-c10-mat-ch8-l3', title:'Using the Theorems', html:'<h3>Worked Example</h3><p>In ΔABC, ∠B is acute, AB = 5, BC = 7, projection of AB on BC = 3. Then AC² = AB² + BC² − 2(BC)(projection) = 25 + 49 − 2×7×3 = 74 − 42 = 32, so AC = √32 = 4√2.</p><p><strong>Exam tip:</strong> identify whether the angle is acute or obtuse first — the sign depends on it.</p>'}],
quiz:[
{q:'The projection of a segment on a line is found by:', options:['Measuring its length','Dropping perpendiculars from its ends','Extending it','Bisecting it'], answer:1, explain:'Feet of perpendiculars mark the projected segment.'},
{q:'In the acute-angle theorem, the correction term is subtracted because:', options:['The angle is small','The projection shortens the effective side','Of Pythagoras','Of similarity'], answer:1, explain:'Minus twice (side × projection) adjusts for the acute angle.'},
{q:'For the side opposite an obtuse angle, the theorem uses:', options:['Minus twice','Plus twice','No correction','Half the product'], answer:1, explain:'Obtuse: a² = b² + c² + 2(side × projection).'},
{q:'The projection theorems are proved using:', options:['Similar triangles','Pythagoras’ theorem','The sine rule','Parallel lines'], answer:1, explain:'Apply Pythagoras to the two right triangles made by the altitude.'},
{q:'If ∠B is acute, AB = 5, BC = 7, projection of AB on BC = 3, then AC² is:', options:['116','32','74','42'], answer:1, explain:'25 + 49 − 2×7×3 = 32.'},
{q:'Projection of a vertical segment onto a horizontal line is:', options:['Its full length','Zero (a point)','Half length','Double length'], answer:1, explain:'Both perpendicular feet coincide.'},
{q:'The altitude from a vertex creates:', options:['Two congruent triangles','Two right triangles','An isosceles triangle','A circle'], answer:1, explain:'The altitude is perpendicular to the base.'},
{q:'In the obtuse case, the projection falls:', options:['On the side itself','On the extension of the side','Inside the triangle','Nowhere'], answer:1, explain:'The foot lies outside, on the produced side.'},
{q:'AC = 4√2 from AC² = 32 because:', options:['√32 = 16','√32 = 4√2','√32 = 8','√32 = 2√8 simplified'], answer:1, explain:'√32 = √(16×2) = 4√2.'},
{q:'The key first step in these problems is to:', options:['Draw a circle','Identify if the angle is acute or obtuse','Measure the altitude','Find the perimeter'], answer:1, explain:'The sign of the correction term depends on it.'}
]},
{id:'kpk-c10-mat-ch9', title:'Chords of a Circle', urdu:'دائرے کے وتر', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch9-l1', title:'Chord Basics', html:'<h3>Definitions</h3><p>A <strong>chord</strong> joins two points on a circle; a <strong>diameter</strong> is the longest chord through the centre. A <strong>segment</strong> is the region cut off by a chord.</p><h3>Theorem 1</h3><p><em>The perpendicular from the centre to a chord <strong>bisects</strong> the chord.</em></p><h3>Theorem 2 (converse)</h3><p><em>The line joining the centre to the midpoint of a chord is <strong>perpendicular</strong> to the chord.</em></p>'},
{id:'kpk-c10-mat-ch9-l2', title:'Equal Chords', html:'<h3>Theorem 3</h3><p><em><strong>Equal chords</strong> of a circle are <strong>equidistant</strong> from the centre.</em></p><h3>Theorem 4 (converse)</h3><p><em>Chords <strong>equidistant</strong> from the centre are <strong>equal</strong>.</em></p><p><strong>Worked example:</strong> radius 5 cm, chord 8 cm: half-chord 4 cm → distance from centre = √(25−16) = 3 cm.</p>'},
{id:'kpk-c10-mat-ch9-l3', title:'Problem Solving', html:'<h3>Strategy</h3><p>Join the centre to the chord’s midpoint to make a right triangle, then use <strong>Pythagoras</strong>.</p><p><strong>Worked example:</strong> two parallel chords 6 cm and 8 cm on opposite sides of the centre, radius 5 cm: distances are 4 cm and 3 cm → distance between chords = 7 cm.</p>'}],
quiz:[
{q:'The longest chord of a circle is the:', options:['Radius','Diameter','Tangent','Arc'], answer:1, explain:'Diameter = 2 × radius, through the centre.'},
{q:'The perpendicular from the centre to a chord:', options:['Trisects it','Bisects it','Misses it','Doubles it'], answer:1, explain:'Theorem 1.'},
{q:'The line from the centre to a chord’s midpoint is:', options:['Parallel to it','Perpendicular to it','Equal to it','A tangent'], answer:1, explain:'The converse theorem.'},
{q:'Equal chords of a circle are:', options:['Parallel','Equidistant from the centre','Perpendicular','Through the centre'], answer:1, explain:'Equal chords sit at equal distances from the centre.'},
{q:'Radius 5 cm, chord 8 cm. Distance from centre:', options:['4 cm','3 cm','6 cm','2 cm'], answer:1, explain:'√(25−16) = 3 cm.'},
{q:'A chord 10 cm long is 12 cm from the centre. The radius is:', options:['13 cm','17 cm','22 cm','11 cm'], answer:0, explain:'r = √(25+144) = √169 = 13 cm.'},
{q:'The region cut off by a chord is called a:', options:['Sector','Segment','Arc','Tangent'], answer:1, explain:'Segment = area between chord and arc.'},
{q:'Chords equidistant from the centre are:', options:['Parallel','Equal','Perpendicular','Diameters'], answer:1, explain:'Converse of the equal-chords theorem.'},
{q:'Two parallel chords 6 cm and 8 cm lie on opposite sides of the centre (r = 5 cm). Their separation is:', options:['1 cm','7 cm','5 cm','12 cm'], answer:1, explain:'Distances 4 cm and 3 cm add to 7 cm.'},
{q:'A line through the centre perpendicular to a chord passes through the chord’s:', options:['End point','Midpoint','Extension','Tangent point'], answer:1, explain:'It bisects the chord.'}
]},
{id:'kpk-c10-mat-ch10', title:'Tangent to a Circle', urdu:'دائرے کا مماس', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch10-l1', title:'What is a Tangent?', html:'<h3>Definition</h3><p>A <strong>tangent</strong> touches a circle at exactly <strong>one point</strong> (the point of contact). A line cutting at two points is a <strong>secant</strong>.</p><h3>Key Theorem</h3><p><em>The tangent at any point is <strong>perpendicular to the radius</strong> through that point.</em> This right angle is the workhorse of tangent problems.</p>'},
{id:'kpk-c10-mat-ch10-l2', title:'Tangents from an External Point', html:'<h3>Theorem</h3><p><em>The two tangents drawn from an external point to a circle are <strong>equal in length</strong>.</em></p><p><strong>Worked example:</strong> from P, 13 cm from centre O (r = 5 cm): tangent length = √(169−25) = √144 = 12 cm.</p><h3>Number of Tangents</h3><p>From an <strong>exterior</strong> point: 2; from a point <strong>on</strong> the circle: 1; from an <strong>interior</strong> point: none.</p>'},
{id:'kpk-c10-mat-ch10-l3', title:'Common Tangents', html:'<h3>Two Circles</h3><p><strong>Direct common tangents</strong> do not cross the line of centres; <strong>transverse common tangents</strong> cross it. At most 4 common tangents exist (2 direct + 2 transverse) when circles are separate.</p><p>Tangent problems almost always reduce to a <strong>right triangle</strong> — find it first.</p>'}],
quiz:[
{q:'A tangent touches a circle at:', options:['Two points','Exactly one point','Three points','No point'], answer:1, explain:'Single-point contact defines a tangent.'},
{q:'The tangent at a point is ___ to the radius through it.', options:['Parallel','Perpendicular','Equal','At 45°'], answer:1, explain:'The fundamental tangent theorem.'},
{q:'Tangents from an external point are:', options:['Unequal','Equal in length','Perpendicular','Parallel'], answer:1, explain:'Symmetry about the line OP makes them equal.'},
{q:'From P, 13 cm from centre (r = 5 cm), tangent length is:', options:['8 cm','12 cm','18 cm','√194 cm'], answer:1, explain:'√(169−25) = 12 cm.'},
{q:'From a point inside a circle, the number of tangents is:', options:['1','2','0','Infinite'], answer:2, explain:'No tangent can be drawn from inside.'},
{q:'From a point on the circle, tangents possible:', options:['0','1','2','4'], answer:1, explain:'Exactly one — perpendicular to the radius there.'},
{q:'Direct common tangents:', options:['Cross the line of centres','Do not cross the line of centres','Touch at one point','Are impossible'], answer:1, explain:'Transverse ones cross it.'},
{q:'Two separate circles have at most ___ common tangents.', options:['2','3','4','6'], answer:2, explain:'2 direct + 2 transverse.'},
{q:'A line cutting a circle at two points is a:', options:['Tangent','Secant','Chord always','Diameter'], answer:1, explain:'Secant = two intersection points.'},
{q:'In tangent problems, the first step is usually to:', options:['Draw a tangent','Find the right triangle','Measure the arc','Find the centre angle'], answer:1, explain:'Radius-to-tangent gives the right angle for Pythagoras.'}
]},
{id:'kpk-c10-mat-ch11', title:'Chords and Arcs', urdu:'وتر اور قوسیں', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch11-l1', title:'Arcs and Central Angles', html:'<h3>Definitions</h3><p>An <strong>arc</strong> is part of the circumference: <strong>minor arc</strong> (&lt; semicircle), <strong>major arc</strong> (&gt; semicircle). The angle at the centre subtended by an arc is its <strong>degree measure</strong>.</p><h3>Theorem</h3><p><em>Equal arcs subtend equal angles at the centre, and conversely.</em></p>'},
{id:'kpk-c10-mat-ch11-l2', title:'Chords and Their Arcs', html:'<h3>Theorem</h3><p><em><strong>Equal chords</strong> cut off <strong>equal arcs</strong> (minor, major and corresponding).</em></p><h3>Converse</h3><p><em><strong>Equal arcs</strong> have <strong>equal chords</strong>.</em></p><p>Proof idea: triangles formed by two radii and the chord are congruent by SSS.</p>'},
{id:'kpk-c10-mat-ch11-l3', title:'Using Arc–Chord Relations', html:'<h3>Worked Example</h3><p>If arc AB = arc CD in the same circle, then chord AB = chord CD — so any length/angle chase can swap between arcs and chords.</p><p><strong>Exam tip:</strong> “subtended by the same chord” and “standing on the same arc” mean the same thing — use whichever form the question gives.</p>'}],
quiz:[
{q:'An arc smaller than a semicircle is a:', options:['Major arc','Minor arc','Sector','Segment'], answer:1, explain:'Minor < 180°.'},
{q:'The degree measure of an arc equals:', options:['Its length','Its central angle','Half its chord','Its radius'], answer:1, explain:'Arc measure is defined by the central angle.'},
{q:'Equal arcs subtend ___ at the centre.', options:['Unequal angles','Equal angles','Right angles','Zero angle'], answer:1, explain:'Arc–angle correspondence.'},
{q:'Equal chords cut off:', options:['Unequal arcs','Equal arcs','No arcs','Semicircles only'], answer:1, explain:'Chord–arc theorem.'},
{q:'If arc AB = arc CD, then:', options:['Chord AB > chord CD','Chord AB = chord CD','AB is a diameter','CD is a tangent'], answer:1, explain:'Equal arcs → equal chords (converse).'},
{q:'The proof of the chord–arc theorem uses:', options:['Pythagoras','SSS congruence','Parallel lines','Similar triangles'], answer:1, explain:'Two radii + chord form SSS-congruent triangles.'},
{q:'A semicircle subtends ___ at the centre.', options:['90°','180°','360°','270°'], answer:1, explain:'Half the full 360°.'},
{q:'“Standing on the same arc” means:', options:['Same chord','Same tangent','Same radius','Same centre'], answer:0, explain:'Angles on the same arc stand on the same chord.'},
{q:'Major arc + minor arc (same endpoints) equals:', options:['90°','180°','360°','0°'], answer:2, explain:'Together they make the full circle.'},
{q:'In congruent circles, equal chords subtend:', options:['Unequal angles','Equal angles at the centres','Different arcs','No angles'], answer:1, explain:'The theorem holds across congruent circles.'}
]},
{id:'kpk-c10-mat-ch12', title:'Angle in a Segment of a Circle', urdu:'دائرے کے قطعے میں زاویہ', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch12-l1', title:'Angles in the Same Segment', html:'<h3>Theorem</h3><p><em>Angles in the <strong>same segment</strong> of a circle are <strong>equal</strong>.</em></p><p>All angles standing on chord AB on the same side are equal — the key to many “find the angle” questions.</p>'},
{id:'kpk-c10-mat-ch12-l2', title:'Angle in a Semicircle', html:'<h3>Theorem</h3><p><em>The angle in a <strong>semicircle</strong> is a <strong>right angle</strong>.</em></p><p><strong>Worked example:</strong> AB is a diameter; any point P on the circle gives ∠APB = 90°. Converse: if ∠APB = 90°, then AB is a diameter.</p>'},
{id:'kpk-c10-mat-ch12-l3', title:'Cyclic Quadrilaterals', html:'<h3>Theorem</h3><p><em>Opposite angles of a <strong>cyclic quadrilateral</strong> are <strong>supplementary</strong> (sum 180°).</em></p><p><strong>Worked example:</strong> ABCD cyclic with ∠A = 70° → ∠C = 110°. Converse: if opposite angles sum to 180°, the quadrilateral is cyclic.</p><p><strong>Exam tip:</strong> “cyclic” in the question is a flashing signal for these two theorems.</p>'}],
quiz:[
{q:'Angles in the same segment are:', options:['Supplementary','Equal','Complementary','Unequal'], answer:1, explain:'The same-segment theorem.'},
{q:'The angle in a semicircle is:', options:['60°','90°','180°','45°'], answer:1, explain:'Thales’ theorem.'},
{q:'AB is a diameter and P is on the circle. ∠APB equals:', options:['45°','90°','180°','60°'], answer:1, explain:'Angle in a semicircle.'},
{q:'In a cyclic quadrilateral, opposite angles are:', options:['Equal','Supplementary','Complementary','Right angles'], answer:1, explain:'They sum to 180°.'},
{q:'ABCD is cyclic with ∠A = 70°. ∠C equals:', options:['70°','110°','90°','140°'], answer:1, explain:'180° − 70° = 110°.'},
{q:'If ∠APB = 90° with P on the circle, then AB is a:', options:['Chord','Diameter','Tangent','Radius'], answer:1, explain:'Converse of the semicircle theorem.'},
{q:'A quadrilateral with opposite angles summing to 180° is:', options:['A trapezium','Cyclic','A kite','Impossible'], answer:1, explain:'Converse of the cyclic quadrilateral theorem.'},
{q:'Angles standing on the same chord on the same side are:', options:['Different','Equal','Supplementary','Zero'], answer:1, explain:'Same segment → equal angles.'},
{q:'The exterior angle of a cyclic quadrilateral equals:', options:['The adjacent angle','The interior opposite angle','90°','180°'], answer:1, explain:'Exterior = interior opposite (from supplementary pairs).'},
{q:'Which quadrilateral is always cyclic?', options:['Trapezium','Rectangle','Kite','Parallelogram'], answer:1, explain:'A rectangle’s opposite angles sum to 180°.'}
]},
{id:'kpk-c10-mat-ch13', title:'Practical Geometry — Circles', urdu:'عملی جیومیٹری — دائرے', comingSoon:false, lessons:[
{id:'kpk-c10-mat-ch13-l1', title:'Circumscribed Circle', html:'<h3>Circumcircle</h3><p>The circle through a triangle’s <strong>three vertices</strong>. <strong>Centre = circumcentre</strong> = intersection of the sides’ <strong>perpendicular bisectors</strong>.</p><p><strong>Steps:</strong> bisect two sides with compass; their meeting point is the centre; radius = distance to any vertex; draw the circle.</p>'},
{id:'kpk-c10-mat-ch13-l2', title:'Inscribed and Escribed Circles', html:'<h3>Incircle</h3><p>Touching all three sides <strong>inside</strong>. <strong>Centre = incentre</strong> = intersection of <strong>angle bisectors</strong>; radius = perpendicular to any side.</p><h3>Escribed Circle</h3><p>Touching one side <strong>externally</strong> and the extensions of the other two — centre at the meeting of two <strong>exterior</strong> angle bisectors and one interior bisector.</p>'},
{id:'kpk-c10-mat-ch13-l3', title:'Tangents from an External Point', html:'<h3>Construction</h3><p>Given point P outside a circle with centre O:</p><ol><li>Join OP and bisect it (midpoint M).</li><li>Draw a circle with centre M and radius MO — it cuts the given circle at T₁, T₂.</li><li>PT₁ and PT₂ are the two tangents.</li></ol><p>Why it works: ∠OT₁P is an angle in a semicircle → 90°, so PT₁ ⊥ radius.</p>'}],
quiz:[
{q:'The circumcentre is the intersection of the:', options:['Angle bisectors','Perpendicular bisectors of the sides','Medians','Altitudes'], answer:1, explain:'Equidistant from all vertices.'},
{q:'The circumcircle passes through the triangle’s:', options:['Midpoints','Three vertices','Incentre','Sides’ midpoints only'], answer:1, explain:'Circumscribed = through the vertices.'},
{q:'The incentre is the intersection of the:', options:['Perpendicular bisectors','Angle bisectors','Medians','Altitudes'], answer:1, explain:'Equidistant from all sides.'},
{q:'The incircle touches:', options:['The vertices','All three sides internally','One side only','The extensions'], answer:1, explain:'Inscribed within the triangle.'},
{q:'An escribed circle touches:', options:['All sides internally','One side externally and extensions of the other two','Only vertices','Nothing'], answer:1, explain:'It sits outside, tangent to one side and two extensions.'},
{q:'To draw tangents from external point P, first:', options:['Draw any tangent','Join OP and bisect it','Draw the circle bigger','Find the arc'], answer:1, explain:'The midpoint M centres the helper circle.'},
{q:'The tangent construction works because:', options:['Of Pythagoras','Angle in a semicircle is 90°','Of equal chords','Of parallel lines'], answer:1, explain:'∠OT₁P = 90° makes PT₁ perpendicular to the radius.'},
{q:'How many tangents can be drawn from an exterior point?', options:['1','2','3','4'], answer:1, explain:'The helper circle cuts the original at two points.'},
{q:'The incentre is the centre of the:', options:['Circumcircle','Incircle','Escribed circle','Helper circle'], answer:1, explain:'Equidistant from the sides.'},
{q:'The circumradius is measured from the circumcentre to a:', options:['Side’s midpoint','Vertex','Tangent point','Base'], answer:1, explain:'All vertices lie on the circumcircle.'}
]}
]});

/* ============ KP BOARD — CLASS 10 ENGLISH ============ */
window.__saMergeCourse({id:'kpk-class10-english', board:'kp', title:'English', urdu:'انگریزی', class:'Class 10', icon:'📖', desc:'KP Board Class 10 English — all 15 units with lessons and quizzes.', chapters:[
{id:'kpk-c10-eng-ch1', title:'Simplicity and Humility of Hazrat Muhammad (S.A.W.W)', urdu:'حضرت محمد ﷺ کی سادگی اور عاجزی', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch1-l1', title:'The Lesson: A Life of Simplicity', html:'<h3>Theme: Simplicity and Humility</h3><p>Humility and simplicity were <strong>ingrained traits</strong> of Hazrat Muhammad’s (peace be upon him) personality. He never made anyone feel small, unwanted or embarrassed, and urged his followers to live decently and kindly.</p><h3>Examples</h3><ul><li>He would <strong>sit wherever a place was available</strong> in an assembly and never sought a prominent seat.</li><li>He <strong>mended his own clothes and shoes</strong> and shared household work.</li><li>He ate simple food, often dates and barley, and sometimes went hungry.</li><li>He met the poor and the rich with the <strong>same warmth</strong>.</li></ul>'},
{id:'kpk-c10-eng-ch1-l2', title:'Vocabulary and Key Words', html:'<h3>Words to Master</h3><ul><li><strong>Humility</strong> — modesty; not thinking yourself above others.</li><li><strong>Simplicity</strong> — plain, unshowy living.</li><li><strong>Ingrained</strong> — deeply fixed in character.</li><li><strong>Embarrassed</strong> — made to feel ashamed.</li><li><strong>Decently</strong> — in a proper, respectable way.</li></ul>'},
{id:'kpk-c10-eng-ch1-l3', title:'Grammar Focus: Direct and Indirect Speech', html:'<h3>Narration Rules</h3><p><strong>Direct:</strong> He said, “I am busy.” → <strong>Indirect:</strong> He said that he was busy.</p><ul><li>Present → past: “I <em>am</em>” → “he <em>was</em>”.</li><li>“Today” → “that day”; “here” → “there”; “this” → “that”.</li><li>Questions: “Are you well?” → He asked <em>if/whether</em> I was well.</li><li>Commands: “Sit down.” → He <em>ordered</em> them to sit down.</li></ul>'}],
quiz:[
{q:'The central theme of the lesson is:', options:['Wealth','Simplicity and humility','Power','Trade'], answer:1, explain:'The lesson presents these as ingrained traits of the Holy Prophet (PBUH).'},
{q:'In an assembly, the Holy Prophet (PBUH) would:', options:['Take the chief seat','Sit wherever a place was available','Stand apart','Arrive last'], answer:1, explain:'He never sought a prominent or elevated place.'},
{q:'“Ingrained” means:', options:['Painted','Deeply fixed in character','Temporary','Forced'], answer:1, explain:'Ingrained traits are deep-rooted.'},
{q:'He never made anyone feel:', options:['Happy','Small, unwanted or embarrassed','Hungry','Tired'], answer:1, explain:'His humility put everyone at ease.'},
{q:'Indirect speech of “I am busy,” he said, is:', options:['He said that he is busy','He said that he was busy','He says he was busy','He said I was busy'], answer:1, explain:'Present shifts to past in indirect narration.'},
{q:'“Are you well?” → He asked:', options:['He asked am I well','He asked if I was well','He asked that I am well','He asked was I well'], answer:1, explain:'Yes/no questions use if/whether with past tense.'},
{q:'“Sit down,” he said →', options:['He said sit down','He ordered them to sit down','He requested sit','He told sit'], answer:1, explain:'Commands become ordered/advised + to-infinitive.'},
{q:'The Holy Prophet (PBUH) mended his own clothes, showing:', options:['Poverty','Humility and self-reliance','Laziness of servants','Dislike of tailors'], answer:1, explain:'He did his own work despite his rank.'},
{q:'“Decently” is closest in meaning to:', options:['Richly','In a proper, respectable way','Quickly','Secretly'], answer:1, explain:'He urged followers to live decently and kindly.'},
{q:'Humility means:', options:['Thinking yourself above others','Modesty — not thinking yourself above others','Being shy always','Avoiding people'], answer:1, explain:'True humility respects everyone equally.'}
]},
{id:'kpk-c10-eng-ch2', title:'The Champions (Amigo Brothers)', urdu:'چیمپئنز', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch2-l1', title:'The Story: Two Friends, One Final', html:'<h3>Piri Thomas’s “Amigo Brothers”</h3><p><strong>Antonio Cruz</strong> and <strong>Felix Vargas</strong>, two best friends from the same neighbourhood, are both brilliant young boxers. Both fight their way to the <strong>Golden Gloves</strong> final — where they must face <strong>each other</strong>.</p><h3>The Fight</h3><p>They agree to fight hard and fair, like true champions, letting the better boxer win. Round after round they exchange fierce blows — yet when the winner is announced, they <strong>leave the ring arm in arm without hearing who won</strong>.</p>'},
{id:'kpk-c10-eng-ch2-l2', title:'Theme and Message', html:'<h3>True Sportsmanship</h3><p>The story celebrates <strong>friendship above victory</strong>. Both boys are champions — not because one wins the trophy, but because both show <strong>courage, fairness and love</strong>.</p><h3>Message</h3><p>Winning is not everything; <strong>how you play</strong> — with honour and respect — matters more. A true champion never sacrifices friendship for a prize.</p>'},
{id:'kpk-c10-eng-ch2-l3', title:'Vocabulary and Key Words', html:'<h3>Words to Master</h3><ul><li><strong>Amigo</strong> — friend (Spanish).</li><li><strong>Bout</strong> — a boxing match.</li><li><strong>Rival</strong> — a competitor.</li><li><strong>Sportsmanship</strong> — fair, generous conduct in sport.</li><li><strong>Devastating</strong> — extremely powerful/destructive.</li></ul>'}],
quiz:[
{q:'“The Champions” is adapted from:', options:['A novel by Dickens','“Amigo Brothers” by Piri Thomas','A film script','A newspaper report'], answer:1, explain:'Piri Thomas’s story of two boxer friends.'},
{q:'The two friends are:', options:['Antonio and Felix','Tom and Jerry','Ali and Ahmed','John and Peter'], answer:0, explain:'Antonio Cruz and Felix Vargas.'},
{q:'They meet in the final of the:', options:['World Cup','Golden Gloves tournament','Olympics','School match'], answer:1, explain:'The Golden Gloves boxing final.'},
{q:'After the fight, the boys:', options:['Quarrel over the result','Leave arm in arm without hearing the winner','Demand a rematch','Stop being friends'], answer:1, explain:'Friendship mattered more than the verdict.'},
{q:'The story’s main theme is:', options:['Revenge','Friendship and true sportsmanship','Money','Fame'], answer:1, explain:'Honour in sport above victory.'},
{q:'“Amigo” means:', options:['Enemy','Friend','Champion','Brother by blood'], answer:1, explain:'Spanish for friend.'},
{q:'A “bout” is a:', options:['Boat','Boxing match','Bet','Bone'], answer:1, explain:'A bout is a contest or match.'},
{q:'Both boys are called champions because they showed:', options:['Brute force','Courage, fairness and love','Trickery','Luck'], answer:1, explain:'True championship is character, not just the trophy.'},
{q:'“Sportsmanship” means:', options:['Winning at all costs','Fair and generous conduct in sport','Wearing sports clothes','Watching games'], answer:1, explain:'Playing hard but fair.'},
{q:'The boys agreed before the final to:', options:['Fix the match','Fight hard and fair','Not fight at all','Share the prize money'], answer:1, explain:'Let the better boxer win — like true champions.'}
]},
{id:'kpk-c10-eng-ch3', title:'Dreams (Poem)', urdu:'خواب (نظم)', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch3-l1', title:'The Poet and the Poem', html:'<h3>Langston Hughes</h3><p><strong>Langston Hughes</strong> (1902–1967), the celebrated African-American poet, urges readers to <strong>hold fast to dreams</strong>.</p><h3>The Poem</h3><blockquote>Hold fast to dreams<br>For if dreams die<br>Life is a broken-winged bird<br>That cannot fly.<br>Hold fast to dreams<br>For when dreams go<br>Life is a barren field<br>Frozen with snow.</blockquote>'},
{id:'kpk-c10-eng-ch3-l2', title:'Explanation', html:'<h3>Stanza 1</h3><p>Without dreams, life is like a <strong>bird with broken wings</strong> — helpless, unable to rise.</p><h3>Stanza 2</h3><p>Without dreams, life is a <strong>barren field frozen with snow</strong> — cold, lifeless, unproductive.</p><h3>Message</h3><p><strong>Dreams give life purpose and flight.</strong> Never abandon your hopes, however hard life becomes.</p>'},
{id:'kpk-c10-eng-ch3-l3', title:'Figures of Speech and Vocabulary', html:'<h3>Figures of Speech</h3><ul><li><strong>Metaphor:</strong> life <em>is</em> a broken-winged bird; life <em>is</em> a barren field (no “like”).</li><li><strong>Repetition:</strong> “Hold fast to dreams” opens both stanzas — for emphasis.</li><li><strong>Imagery:</strong> bird, field, snow.</li></ul><h3>Vocabulary</h3><ul><li><strong>Hold fast</strong> — grip firmly; <strong>barren</strong> — unable to produce; <strong>broken-winged</strong> — crippled, helpless.</li></ul>'}],
quiz:[
{q:'“Dreams” was written by:', options:['Robert Frost','Langston Hughes','Walt Whitman','Maya Angelou'], answer:1, explain:'The African-American poet Langston Hughes.'},
{q:'Life without dreams is compared to a:', options:['Flying eagle','Broken-winged bird','Singing nightingale','Caged lion'], answer:1, explain:'Helpless, unable to fly.'},
{q:'Life without dreams is also a:', options:['Green garden','Barren field frozen with snow','Flowing river','Busy market'], answer:1, explain:'Cold, lifeless, unproductive.'},
{q:'These comparisons are:', options:['Similes','Metaphors','Hyperboles','Puns'], answer:1, explain:'Direct identification without “like” or “as”.'},
{q:'“Hold fast to dreams” is repeated to:', options:['Fill space','Emphasise the message','Rhyme','Confuse'], answer:1, explain:'Repetition stresses never abandoning hope.'},
{q:'“Barren” means:', options:['Fertile','Unable to produce','Green','Wide'], answer:1, explain:'A barren field grows nothing.'},
{q:'The poem’s message is:', options:['Sleep more','Never give up your dreams','Birds are beautiful','Winter is harsh'], answer:1, explain:'Dreams give life purpose and flight.'},
{q:'“Hold fast” means:', options:['Run fast','Grip firmly','Let go','Forget'], answer:1, explain:'Cling tightly to your dreams.'},
{q:'The poem has ___ stanzas.', options:['One','Two','Three','Four'], answer:1, explain:'Two quatrains with parallel structure.'},
{q:'A “broken-winged bird” symbolises a life:', options:['Full of joy','Without hope or purpose','Of travel','Of song'], answer:1, explain:'Unable to rise — the image of despair.'}
]},
{id:'kpk-c10-eng-ch4', title:'Population Growth and its Impact on Environment', urdu:'آبادی میں اضافہ اور ماحول پر اثرات', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch4-l1', title:'The Problem', html:'<h3>Rapid Growth</h3><p>Pakistan’s population has grown explosively — more mouths to feed, more homes, schools and hospitals needed every year.</p><h3>Impacts on the Environment</h3><ul><li><strong>Deforestation</strong> for housing and fuel.</li><li><strong>Pollution</strong> — more waste, smoke and sewage.</li><li><strong>Water shortage</strong> as demand outruns supply.</li><li><strong>Pressure on farmland</strong> — fertile land turned into housing.</li></ul>'},
{id:'kpk-c10-eng-ch4-l2', title:'Effects on Society and Economy', html:'<h3>Consequences</h3><ul><li><strong>Unemployment</strong> — jobs cannot keep pace.</li><li><strong>Poverty</strong> — incomes spread thin.</li><li><strong>Overcrowded</strong> schools, hospitals and transport.</li><li>Slower <strong>economic growth</strong> per person.</li></ul>'},
{id:'kpk-c10-eng-ch4-l3', title:'Solutions and Vocabulary', html:'<h3>What Can Be Done?</h3><ul><li><strong>Family planning</strong> and awareness.</li><li><strong>Education</strong>, especially of girls.</li><li><strong>Sustainable development</strong> — meeting needs without destroying nature.</li><li>Better <strong>resource management</strong>.</li></ul><h3>Vocabulary</h3><p><strong>Overpopulation, sustainable, resource, dense, per capita, planning.</strong></p>'}],
quiz:[
{q:'Rapid population growth puts the greatest pressure on:', options:['Mountains','Natural resources and services','Deserts','Oceans only'], answer:1, explain:'Food, water, housing, schools and hospitals all strain.'},
{q:'Deforestation is linked to population growth because:', options:['Trees dislike people','Land is cleared for housing and fuel','People plant trees','Forests grow faster'], answer:1, explain:'More people need more space and firewood.'},
{q:'Overpopulation leads to:', options:['More jobs per person','Unemployment and poverty','Empty schools','Faster growth for all'], answer:1, explain:'Jobs and incomes cannot keep pace with numbers.'},
{q:'“Sustainable development” means:', options:['Fast growth at any cost','Meeting needs without harming future generations','Stopping all growth','Building dams only'], answer:1, explain:'Development that nature can support long-term.'},
{q:'A key solution to rapid growth is:', options:['More imports','Family planning and education','Bigger cities','More cars'], answer:1, explain:'Awareness and planning slow growth rates.'},
{q:'“Per capita” means:', options:['Per country','Per person','Per year','Per city'], answer:1, explain:'Per head of population.'},
{q:'Overcrowded hospitals are a result of:', options:['Too many doctors','Population pressure','Good health','New buildings'], answer:1, explain:'Patients outnumber facilities.'},
{q:'Educating girls helps control population because:', options:['It is a hobby','Educated women plan smaller families','It builds schools','It is a law'], answer:1, explain:'Education correlates strongly with lower birth rates.'},
{q:'Water shortage worsens with population growth since:', options:['Rain decreases','Demand outruns supply','Rivers dry from heat','Pipes leak'], answer:1, explain:'More users share the same water.'},
{q:'Fertile farmland is lost when it is:', options:['Irrigated','Converted into housing','Ploughed','Fertilised'], answer:1, explain:'Urban sprawl eats agricultural land.'}
]},
{id:'kpk-c10-eng-ch5', title:'The Great Masjid of Cordoba and Iqbal', urdu:'قرطبہ کی عظیم مسجد اور اقبال', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch5-l1', title:'The Masjid of Cordoba', html:'<h3>A Wonder of Muslim Spain</h3><p>The <strong>Great Masjid of Cordoba</strong> (Masjid-e-Qurtaba), begun by <strong>Abdur Rahman I</strong> in 784 AD, was among the world’s grandest mosques — a <strong>forest of 856 marble columns</strong> with red-and-white arches.</p><h3>Iqbal’s Visit</h3><p>In <strong>1932</strong>, Allama Iqbal visited Cordoba and was so moved that he wrote his famous Urdu poem <strong>“Masjid-e-Qurtaba”</strong>, seeing in it the glory and decline of Muslim civilisation.</p>'},
{id:'kpk-c10-eng-ch5-l2', title:'Message of the Lesson', html:'<h3>Glory and Lesson</h3><p>The masjid stands as proof of what Muslims achieved through <strong>faith, knowledge and unity</strong> — Cordoba was once Europe’s centre of learning. Its later fate reminds Muslims that <strong>glory must be guarded by character and action</strong>, not only monuments.</p>'},
{id:'kpk-c10-eng-ch5-l3', title:'Vocabulary and Key Words', html:'<h3>Words to Master</h3><ul><li><strong>Grandeur</strong> — magnificence.</li><li><strong>Civilisation</strong> — an advanced human society.</li><li><strong>Heritage</strong> — what we inherit from the past.</li><li><strong>Architecture</strong> — the art of building design.</li><li><strong>Symbol</strong> — something standing for an idea.</li></ul>'}],
quiz:[
{q:'The Great Masjid of Cordoba was begun by:', options:['Tariq bin Ziyad','Abdur Rahman I','Harun al-Rashid','Salahuddin'], answer:1, explain:'In 784 AD in Muslim Spain.'},
{q:'The masjid is famous for its:', options:['Golden dome','Forest of 856 columns','Tall minaret','Underground halls'], answer:1, explain:'Its hypostyle hall of jasper and marble columns.'},
{q:'Iqbal visited Cordoba in:', options:['1920','1932','1947','1905'], answer:1, explain:'The visit inspired “Masjid-e-Qurtaba”.'},
{q:'Iqbal wrote the poem:', options:['Shikwa','Masjid-e-Qurtaba','Tulu-e-Islam','Khizr-e-Rah'], answer:1, explain:'His celebrated Cordoba poem.'},
{q:'Cordoba under the Muslims was:', options:['A small village','A centre of learning in Europe','A desert fort','A port only'], answer:1, explain:'Its libraries and scholars led Europe.'},
{q:'The lesson’s message is that glory needs:', options:['Big buildings only','Faith, knowledge, unity and character','Wealth alone','Luck'], answer:1, explain:'Monuments fade; living values sustain nations.'},
{q:'“Heritage” means:', options:['Money','What we inherit from the past','A building','A war'], answer:1, explain:'Cultural inheritance.'},
{q:'“Grandeur” is closest in meaning to:', options:['Smallness','Magnificence','Sadness','Speed'], answer:1, explain:'Impressive greatness.'},
{q:'The masjid symbolises:', options:['Defeat','The golden age of Muslim Spain','Trade','Farming'], answer:1, explain:'A symbol of Islamic civilisation’s peak.'},
{q:'“Architecture” is:', options:['The art of building design','A type of prayer','A pillar','A poem'], answer:0, explain:'Design and construction of buildings.'}
]},
{id:'kpk-c10-eng-ch6', title:'In Spite of War (Poem)', urdu:'جنگ کے باوجود (نظم)', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch6-l1', title:'The Poet and the Poem', html:'<h3>Angela Morgan</h3><p><strong>Angela Morgan</strong> (1875–1957), the American poet, wrote “In Spite of War” during <strong>World War I</strong>.</p><h3>The Poem’s Heart</h3><blockquote>In spite of war, in spite of death,<br>In spite of all man’s sufferings,<br>Something within me laughs and sings<br>And I must praise with all my breath.</blockquote><p>Amid horror, the poet’s spirit <strong>laughs and sings</strong> — life’s beauty refuses to die.</p>'},
{id:'kpk-c10-eng-ch6-l2', title:'Explanation: Nature Against War', html:'<h3>Images of Hope</h3><ul><li><strong>“Lilacs are blooming at my gate, / Tulips are tripping down the path”</strong> — flowers ignore the war.</li><li><strong>“‘Courage!’ the morning-glory saith; / ‘Rejoice!’ the daisy murmureth”</strong> — flowers <em>speak</em> encouragement.</li><li><strong>“Though guns may roar and cannon boom, / Roses are born and gardens bloom”</strong> — creation defeats destruction.</li></ul><p>The close: <strong>“Wake from the nightmare! Look and see / That life is naught but ecstasy / In spite of war, in spite of death!”</strong></p>'},
{id:'kpk-c10-eng-ch6-l3', title:'Figures of Speech and Vocabulary', html:'<h3>Figures of Speech</h3><ul><li><strong>Personification:</strong> flowers speak (“Courage!”, “Rejoice!”); clouds “romp”.</li><li><strong>Repetition:</strong> “In spite of war, in spite of…” — a drumbeat of defiance.</li><li><strong>Contrast:</strong> guns vs roses, wrath vs lilacs.</li></ul><h3>Vocabulary</h3><ul><li><strong>Wrath</strong> — extreme anger; <strong>murmureth</strong> — murmurs (old form); <strong>ecstasy</strong> — overwhelming joy; <strong>saith</strong> — says (old form).</li></ul>'}],
quiz:[
{q:'“In Spite of War” was written by:', options:['Emily Dickinson','Angela Morgan','Walt Whitman','Sylvia Plath'], answer:1, explain:'The American poet, during World War I.'},
{q:'“Something within me laughs and sings” shows the poet’s:', options:['Madness','Uncrushable hope','Fear','Anger'], answer:1, explain:'Her spirit defies war’s horror.'},
{q:'“Lilacs are blooming at my gate” suggests:', options:['War is over','Nature continues despite war','The poet is gardening','Winter has come'], answer:1, explain:'Life blooms even amid destruction.'},
{q:'“‘Courage!’ the morning-glory saith” is:', options:['Simile','Personification','Hyperbole','Oxymoron'], answer:1, explain:'A flower speaks like a person.'},
{q:'The contrast “guns may roar… roses are born” shows:', options:['War is good','Creation defeats destruction','Gardens cause wars','Roses are loud'], answer:1, explain:'Life renews itself despite violence.'},
{q:'“Wrath” means:', options:['Joy','Extreme anger','Fear','Peace'], answer:1, explain:'Violent anger.'},
{q:'The repeated phrase “In spite of war” acts as:', options:['A mistake','A drumbeat of defiance','A rhyme filler','A question'], answer:1, explain:'Repetition hammers home resistance to despair.'},
{q:'“Life is naught but ecstasy” means life is:', options:['Painful','Overwhelmingly joyful','Boring','Short'], answer:1, explain:'Ecstasy = intense joy.'},
{q:'The poem’s message is:', options:['War is glorious','Find hope and beauty even in dark times','Avoid flowers','Sleep more'], answer:1, explain:'Optimism drawn from nature’s persistence.'},
{q:'“Wake from the nightmare!” calls the reader to:', options:['Sleep','See life’s beauty beyond war’s horror','Fight','Flee'], answer:1, explain:'War is the nightmare; life is the waking joy.'}
]},
{id:'kpk-c10-eng-ch7', title:'The Aged Mother', urdu:'بوڑھی ماں', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch7-l1', title:'The Story: A Cruel Order', html:'<h3>The Japanese Tale</h3><p>A poor farmer lives with his <strong>aged mother</strong>. The cruel governor orders that <strong>all old people be abandoned on the mountain</strong> to die.</p><h3>The Journey</h3><p>The loving son carries his mother up the mountain. On the way, she <strong>breaks twigs and drops them</strong> to mark the path — so that <em>he</em> can find his way back safely. Moved by her selfless love, the son <strong>cannot abandon her</strong> and secretly brings her home.</p>'},
{id:'kpk-c10-eng-ch7-l2', title:'The Mother’s Wisdom', html:'<h3>The Impossible Tasks</h3><p>The governor demands impossible things — e.g. <strong>a rope of ashes</strong>. The hidden mother’s wisdom solves them: twist a rope of straw, <strong>soak it in salt water, dry it, then burn it</strong> — an ash rope remains.</p><h3>The Repeal</h3><p>Amazed, the governor learns the wisdom came from an old mother — and <strong>repeals the cruel law</strong>. The aged are honoured again.</p>'},
{id:'kpk-c10-eng-ch7-l3', title:'Theme and Vocabulary', html:'<h3>Theme</h3><p><strong>Respect for elders:</strong> old age brings <strong>wisdom</strong>; a society that discards its elders discards its own wisdom. <strong>Filial love</strong> — the son’s devotion — is the story’s heart.</p><h3>Vocabulary</h3><ul><li><strong>Aged</strong> — very old; <strong>abandon</strong> — leave behind; <strong>repeal</strong> — cancel a law; <strong>selfless</strong> — caring for others above self; <strong>filial</strong> — of a son/daughter.</li></ul>'}],
quiz:[
{q:'“The Aged Mother” is a tale from:', options:['China','Japan','Arabia','Greece'], answer:1, explain:'A classic Japanese folktale.'},
{q:'The governor ordered that old people be:', options:['Honoured','Abandoned on the mountain','Given pensions','Made ministers'], answer:1, explain:'The cruel decree drives the story.'},
{q:'On the mountain path, the mother dropped twigs to:', options:['Feed birds','Mark the path for her son’s safe return','Make a fire','Build a hut'], answer:1, explain:'Her selfless love thought of his safety, not hers.'},
{q:'The son brought his mother back because:', options:['He feared the governor','He was moved by her selfless love','He was tired','She ordered him'], answer:1, explain:'Her love made abandonment impossible.'},
{q:'The rope of ashes was made by:', options:['Magic','Twisting straw rope, soaking in salt water, drying and burning','Buying it','Praying'], answer:1, explain:'The mother’s clever method.'},
{q:'The governor repealed the law when he learned:', options:['The son was rich','The wisdom came from an old mother','It rained','The mountain fell'], answer:1, explain:'He saw the value of the aged.'},
{q:'The story’s theme is:', options:['Obey cruel laws','Respect for elders and their wisdom','Mountains are dangerous','Twigs are useful'], answer:1, explain:'Old age brings wisdom worth honouring.'},
{q:'“Repeal” means:', options:['Repeat','Cancel (a law)','Approve','Write'], answer:1, explain:'To repeal is to revoke officially.'},
{q:'“Filial love” is love:', options:['Of friends','Of a son/daughter for parents','Of pets','Of country'], answer:1, explain:'Filial = relating to children’s duty to parents.'},
{q:'The mother is best described as:', options:['Selfish','Selfless and wise','Cruel','Foolish'], answer:1, explain:'She gave wisdom and love even facing death.'}
]},
{id:'kpk-c10-eng-ch8', title:'Women’s Role in the Pakistan Movement', urdu:'تحریکِ پاکستان میں خواتین کا کردار', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch8-l1', title:'The Lesson: Women Beside Men', html:'<h3>Leaders</h3><ul><li><strong>Fatima Jinnah</strong> (Madar-e-Millat) — the Quaid’s closest companion and supporter.</li><li><strong>Begum Rana Liaquat Ali Khan</strong> — organised women, founded APWA later.</li><li><strong>Begum Jahanara Shahnawaz</strong> — represented Muslim women at the Round Table Conference.</li><li><strong>Begum Shaista Ikramullah</strong> — writer and activist.</li></ul>'},
{id:'kpk-c10-eng-ch8-l2', title:'Their Work', html:'<h3>Contributions</h3><ul><li>Formed the <strong>women’s wing</strong> of the Muslim League.</li><li>Led <strong>processions and protests</strong> for Pakistan.</li><li>Raised <strong>funds</strong> and spread the message in homes.</li><li>Faced <strong>arrests and hardships</strong> with courage.</li></ul><p>Pakistan was won by the <strong>joint struggle</strong> of men and women.</p>'},
{id:'kpk-c10-eng-ch8-l3', title:'Vocabulary and Key Words', html:'<h3>Words to Master</h3><ul><li><strong>Movement</strong> — an organised struggle for a cause.</li><li><strong>Procession</strong> — a marching demonstration.</li><li><strong>Sacrifice</strong> — giving up something precious.</li><li><strong>Emancipation</strong> — freeing from restrictions.</li><li><strong>Companion</strong> — a close partner.</li></ul>'}],
quiz:[
{q:'Fatima Jinnah is honoured as:', options:['Madar-e-Watan','Madar-e-Millat','Khatoon-e-Awwal','Sher Bano'], answer:1, explain:'Mother of the Nation.'},
{q:'Begum Jahanara Shahnawaz represented Muslim women at the:', options:['UN','Round Table Conference','Simla talks','Lahore session'], answer:1, explain:'She voiced women’s demands in London.'},
{q:'Begum Rana Liaquat Ali Khan is known for:', options:['Poetry','Organising women and social work','Sports','Science'], answer:1, explain:'She mobilised women for the cause and later founded APWA.'},
{q:'The women’s wing belonged to the:', options:['Congress','Muslim League','Khilafat Committee','Red Cross'], answer:1, explain:'The League’s organised women’s section.'},
{q:'Women contributed by leading:', options:['Armies','Processions and protests','Factories','Courts'], answer:1, explain:'Public demonstrations showed mass support.'},
{q:'The lesson’s message is that Pakistan was won by:', options:['Men alone','The joint struggle of men and women','Foreign help','Luck'], answer:1, explain:'Women’s sacrifices matched men’s.'},
{q:'“Sacrifice” means:', options:['Celebration','Giving up something precious','Earning money','Travelling'], answer:1, explain:'Giving up comfort, safety or wealth for a cause.'},
{q:'“Emancipation” means:', options:['Imprisonment','Freeing from restrictions','Education only','Voting'], answer:1, explain:'Liberation from social bonds.'},
{q:'Begum Shaista Ikramullah was a:', options:['Scientist','Writer and activist','General','Judge'], answer:1, explain:'She wrote and campaigned for the cause.'},
{q:'A “procession” is a:', options:['Meeting indoors','Marching demonstration','Feast','Court case'], answer:1, explain:'An organised public march.'}
]},
{id:'kpk-c10-eng-ch9', title:'Equipment (Poem)', urdu:'سازوسامان (نظم)', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch9-l1', title:'The Poet and the Poem', html:'<h3>Edgar Guest</h3><p><strong>Edgar A. Guest</strong> (1881–1959), the “people’s poet”, wrote “Equipment” to inspire self-reliance.</p><h3>The Poem’s Call</h3><blockquote>Figure it out for yourself, my lad,<br>You’ve all that the greatest of men have had…</blockquote><p>You own the same <strong>equipment</strong> as the greatest: <strong>two arms, two hands, two legs, two eyes, and a brain</strong>. “So start for the top and say, ‘I can.’”</p>'},
{id:'kpk-c10-eng-ch9-l2', title:'Explanation', html:'<h3>Stanza-wise</h3><ul><li>The great began with <strong>the same body and brain</strong> you have — no excuses.</li><li><strong>“Courage must come from the soul within, / The man must furnish the will to win.”</strong> — success needs inner will.</li><li>Do not wait for luck; <strong>start where you stand</strong> and climb.</li></ul><h3>Message</h3><p><strong>You are fully equipped for greatness</strong> — what you lack is never tools, only will.</p>'},
{id:'kpk-c10-eng-ch9-l3', title:'Figures of Speech and Vocabulary', html:'<h3>Figures of Speech</h3><ul><li><strong>Repetition:</strong> “I can” spirit; the equipment list.</li><li><strong>Direct address:</strong> “my lad” — the poet talks to <em>you</em>.</li><li><strong>Alliteration:</strong> “start… stand”, “will to win”.</li></ul><h3>Vocabulary</h3><ul><li><strong>Equipment</strong> — tools for a task; <strong>furnish</strong> — supply; <strong>lad</strong> — a boy/young man.</li></ul>'}],
quiz:[
{q:'“Equipment” was written by:', options:['Edgar Allan Poe','Edgar Guest','Robert Frost','Kipling'], answer:1, explain:'Edgar A. Guest, the people’s poet.'},
{q:'According to the poem, you have the same equipment as:', options:['Kings only','The greatest of men','Athletes only','No one'], answer:1, explain:'Two arms, two legs, two eyes and a brain — like all great people.'},
{q:'“Courage must come from the soul within” means success needs:', options:['Money','Inner will','Luck','Friends'], answer:1, explain:'The will to win must be furnished by yourself.'},
{q:'The poem advises the lad to:', options:['Wait for luck','Start where he stands and say “I can”','Blame fate','Copy others'], answer:1, explain:'Action now, with self-belief.'},
{q:'“Furnish” in the poem means:', options:['Decorate','Supply','Polish','Buy'], answer:1, explain:'“The man must furnish the will to win.”'},
{q:'The poet directly addresses the reader as:', options:['Sir','My lad','Friend','Child'], answer:1, explain:'Direct address makes it personal.'},
{q:'The poem’s message is:', options:['Buy better tools','You are fully equipped — use willpower','Great men are born lucky','Avoid hard work'], answer:1, explain:'Self-reliance, not excuses.'},
{q:'“Will to win” shows:', options:['Alliteration','Simile','Metaphor','Pun'], answer:0, explain:'Repeated “w” sound.'},
{q:'The “equipment” listed includes:', options:['A car and money','Two arms, two hands, two legs, two eyes, a brain','Books and pens','A degree'], answer:1, explain:'The natural gifts everyone shares.'},
{q:'“Figure it out for yourself” encourages:', options:['Cheating','Self-reliance','Asking others','Giving up'], answer:1, explain:'Solve your own problems.'}
]},
{id:'kpk-c10-eng-ch10', title:'Water Scarcity in Pakistan', urdu:'پاکستان میں پانی کی قلت', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch10-l1', title:'The Crisis', html:'<h3>Shrinking Water</h3><p>Pakistan’s per-person water availability has fallen from about <strong>5,000 cubic metres (1951)</strong> towards <strong>1,000</strong> — the scarcity line. The country is becoming <strong>water-stressed</strong>.</p><h3>Causes</h3><ul><li><strong>Population growth</strong> — more users, same rivers.</li><li><strong>Climate change</strong> — melting glaciers, erratic rains.</li><li><strong>Poor storage</strong> — little dam capacity; floodwater wasted.</li><li><strong>Wastage</strong> — flood irrigation, leaking pipes.</li></ul>'},
{id:'kpk-c10-eng-ch10-l2', title:'Effects', html:'<h3>Consequences</h3><ul><li><strong>Farms</strong> suffer — crops fail, food prices rise.</li><li><strong>Cities</strong> face shortages; tanker mafias thrive.</li><li><strong>Health</strong> — unsafe water spreads disease.</li><li><strong>Energy</strong> — less hydropower.</li></ul>'},
{id:'kpk-c10-eng-ch10-l3', title:'Solutions and Vocabulary', html:'<h3>What Can Be Done?</h3><ul><li>Build <strong>dams</strong> (Diamer-Bhasha, Mohmand).</li><li><strong>Drip irrigation</strong> instead of flood irrigation.</li><li><strong>Line canals</strong> to stop seepage; fix leaks.</li><li><strong>Rainwater harvesting</strong>; public awareness to <strong>save water</strong>.</li></ul><h3>Vocabulary</h3><p><strong>Scarcity, per capita, reservoir, irrigation, conserve, stressed.</strong></p>'}],
quiz:[
{q:'Per-person water availability in Pakistan has fallen from ~5,000 m³ (1951) towards:', options:['4,000 m³','1,000 m³','10,000 m³','500 m³'], answer:1, explain:'Approaching the scarcity threshold.'},
{q:'A major cause of water scarcity is:', options:['Too many dams','Population growth with fixed supply','Heavy rainfall','Cold weather'], answer:1, explain:'More users share the same rivers.'},
{q:'Climate change affects water through:', options:['More snow','Melting glaciers and erratic rains','Less sun','Cold rivers'], answer:1, explain:'Glacier melt and shifting monsoons disrupt supply.'},
{q:'Flood irrigation is a problem because it:', options:['Is modern','Wastes huge amounts of water','Is cheap','Needs no canals'], answer:1, explain:'Most water evaporates or seeps away.'},
{q:'Diamer-Bhasha dam will help by:', options:['Making electricity only','Storing water and generating power','Stopping rain','Cooling cities'], answer:1, explain:'Storage plus hydropower.'},
{q:'Drip irrigation:', options:['Floods fields','Delivers water drop by drop to roots','Needs more water','Is ancient'], answer:1, explain:'Highly efficient watering.'},
{q:'“Conserve” means:', options:['Waste','Protect and save','Spend','Pollute'], answer:1, explain:'To conserve water is to use it wisely.'},
{q:'Water scarcity hurts farms by:', options:['Increasing rain','Causing crop failure','Cooling soil','Adding nutrients'], answer:1, explain:'Crops die without water; food prices rise.'},
{q:'Lining canals prevents:', options:['Floods','Seepage losses','Evaporation fully','Theft'], answer:1, explain:'Lined channels stop water soaking away.'},
{q:'A “reservoir” is a:', options:['River','Large stored-water lake','Well','Pipe'], answer:1, explain:'Dams create reservoirs.'}
]},
{id:'kpk-c10-eng-ch11', title:'Genetically Modified Organisms (GMOs)', urdu:'جینیاتی طور پر تبدیل شدہ جاندار', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch11-l1', title:'What are GMOs?', html:'<h3>Definition</h3><p><strong>Genetically Modified Organisms</strong> have had their <strong>genes altered</strong> in a lab to add useful traits — e.g. <strong>Bt cotton</strong> (pest-resistant), <strong>golden rice</strong> (vitamin-A rich).</p><h3>How?</h3><p>Scientists insert a gene from one organism into another’s DNA — e.g. a bacterial gene into cotton against bollworms.</p>'},
{id:'kpk-c10-eng-ch11-l2', title:'Merits', html:'<h3>Advantages</h3><ul><li><strong>Increased resistance to disease and pests.</strong></li><li><strong>Large yield and greater nutrition</strong> — more food per acre.</li><li>Less pesticide needed; crops for harsh climates.</li></ul>'},
{id:'kpk-c10-eng-ch11-l3', title:'Demerits and Care', html:'<h3>Concerns</h3><ul><li><strong>Unpredictable behaviour</strong> of altered genes.</li><li>May gain <strong>unwanted traits</strong> harming bodies and ecosystems.</li><li><strong>Antibiotic resistance</strong> fears; domino effects in food chains.</li></ul><h3>Safe Use</h3><p>Eat only GM foods that <strong>pass standard safety tests</strong>; avoid those linked to antibiotic resistance. Science must walk with caution.</p>'}],
quiz:[
{q:'A GMO is an organism whose ___ have been altered.', options:['Leaves','Genes','Roots','Flowers'], answer:1, explain:'Genetic modification changes DNA.'},
{q:'Bt cotton is modified to resist:', options:['Drought','Bollworm pests','Floods','Cold'], answer:1, explain:'A bacterial gene kills the pests.'},
{q:'Golden rice is rich in:', options:['Iron','Vitamin A','Protein','Calcium'], answer:1, explain:'Engineered to fight vitamin-A deficiency.'},
{q:'A merit of GMOs is:', options:['Unpredictable genes','Large yield and greater nutrition','More pesticide use','Smaller farms'], answer:1, explain:'More, healthier food per acre.'},
{q:'A demerit of GMOs is:', options:['Higher yield','Unpredictable behaviour of altered genes','Pest resistance','Better nutrition'], answer:1, explain:'Altered genes may act unexpectedly.'},
{q:'GMOs may harm the ecosystem through:', options:['More oxygen','Unwanted traits spreading','Cleaner air','Fewer insects always'], answer:1, explain:'Gene flow can disturb natural balances.'},
{q:'Safe GM food is food that has:', options:['Nice packaging','Passed standard safety tests','Foreign labels','Low price'], answer:1, explain:'Testing first — the lesson’s advice.'},
{q:'Antibiotic resistance is a concern because GM foods might:', options:['Taste bad','Reduce medicine effectiveness','Cost more','Look odd'], answer:1, explain:'Resistance genes could spread to germs.'},
{q:'Genes are transferred in genetic engineering as:', options:['Whole plants','DNA segments','Proteins only','Water'], answer:1, explain:'Specific genes are inserted into DNA.'},
{q:'The lesson’s balanced view is:', options:['Ban all GMOs','Use GMOs with safety and caution','Eat only GMOs','Ignore the risks'], answer:1, explain:'Benefits are real, but so are risks.'}
]},
{id:'kpk-c10-eng-ch12', title:'They Have Cut Down the Pines (Poem)', urdu:'انہوں نے صنوبر کاٹ ڈالے (نظم)', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch12-l1', title:'The Poet and the Poem', html:'<h3>Mary Lisle</h3><p><strong>Mary Lisle</strong>, the Australian poetess, mourns the felling of pine trees in this elegy for nature.</p><h3>The Scene</h3><blockquote>They have cut down the pines where they stood;<br>The wind will miss them — the rain,<br>When its silver blind is down.</blockquote><p>The bark is stripped, <strong>needly boughs</strong> and brown <strong>knobby nuts</strong> lie trodden in the ground.</p>'},
{id:'kpk-c10-eng-ch12-l2', title:'Explanation: What Was Lost', html:'<h3>The Friendly Trees</h3><p>The pines were <strong>“kind, friendly trees”</strong> where <strong>small winds sounded all day</strong> and the <strong>sun played hide and seek with shadows</strong> till night.</p><h3>The End</h3><p><strong>“They have cut down the trees and ended now / The gentle colloquy of bough and bough.”</strong> The pines were felled merely <strong>for fence posts by the creek</strong> — <strong>“Wan in the sunlight as ghosts / The naked trunks lie.”</strong> A bird that nested there <strong>will seek in vain</strong>.</p>'},
{id:'kpk-c10-eng-ch12-l3', title:'Figures of Speech and Message', html:'<h3>Figures of Speech</h3><ul><li><strong>Personification:</strong> wind and rain “miss” the trees; trees are “kind, friendly”; trunks lie “as ghosts” (simile).</li><li><strong>Repetition:</strong> “They have cut down the pines” — a hammer-blow of loss.</li><li><strong>Imagery:</strong> silver rain, hide-and-seek shadows, naked trunks.</li></ul><h3>Message</h3><p><strong>Deforestation destroys beauty, wildlife homes and nature’s music</strong> — for petty human needs. A plea to protect trees.</p><h3>Vocabulary</h3><ul><li><strong>Colloquy</strong> — conversation; <strong>wan</strong> — pale and weak; <strong>in vain</strong> — without success.</li></ul>'}],
quiz:[
{q:'“They Have Cut Down the Pines” was written by:', options:['Mary Shelley','Mary Lisle','Emily Dickinson','Angela Morgan'], answer:1, explain:'The Australian poetess.'},
{q:'The pines were cut down to make:', options:['Furniture','Fence posts by the creek','Paper','Houses'], answer:1, explain:'A petty use for noble trees.'},
{q:'“The wind will miss them — the rain” is:', options:['Simile','Personification','Hyperbole','Pun'], answer:1, explain:'Wind and rain feel loss like people.'},
{q:'The trees are called “kind, friendly” — this is:', options:['Metaphor','Personification','Alliteration','Irony'], answer:1, explain:'Human qualities given to trees.'},
{q:'“The gentle colloquy of bough and bough” means:', options:['A fight','The gentle conversation of branches','A storm','Birdsong'], answer:1, explain:'Colloquy = conversation; the wind’s music in branches.'},
{q:'“Wan in the sunlight as ghosts” contains a:', options:['Metaphor','Simile','Hyperbole','Pun'], answer:1, explain:'Comparison with “as”.'},
{q:'“Wan” means:', options:['Strong','Pale and weak','Green','Tall'], answer:1, explain:'The naked trunks look pale and lifeless.'},
{q:'The nesting bird “will seek in vain” — “in vain” means:', options:['With joy','Without success','Quickly','In winter'], answer:1, explain:'Its home is gone forever.'},
{q:'The repeated line “They have cut down the pines” expresses:', options:['Joy','Grief at the loss','Anger at birds','Pride'], answer:1, explain:'Repetition hammers the sorrow.'},
{q:'The poem’s message is:', options:['Cut more trees','Protect trees — deforestation destroys beauty and wildlife','Fences are beautiful','Birds are noisy'], answer:1, explain:'An elegy warning against destroying nature.'}
]},
{id:'kpk-c10-eng-ch13', title:'Hazrat Umar (R.A)', urdu:'حضرت عمرؓ', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch13-l1', title:'The Lesson: A Life of Justice', html:'<h3>The Second Caliph</h3><p><strong>Hazrat Umar ibn al-Khattab (R.A)</strong>, the second rightly-guided Caliph, ruled a vast empire yet lived with <strong>extreme simplicity</strong> — patched clothes, simple food.</p><h3>Justice</h3><p>His justice was legendary: <em>“If a mule stumbles on the road to Iraq, I fear Allah will question Umar about it.”</em> He walked the streets at night to check on his people.</p>'},
{id:'kpk-c10-eng-ch13-l2', title:'Reforms and Achievements', html:'<h3>Administration</h3><ul><li>Started the <strong>Hijri calendar</strong>.</li><li>Set up the <strong>Diwan</strong> (state register) and <strong>qazi courts</strong>.</li><li>Divided the empire into <strong>provinces</strong> with governors.</li></ul><h3>Conquests</h3><p>Persia, Syria, Egypt and <strong>Jerusalem</strong> came under Islam — yet he entered Jerusalem on foot, sharing his camel with his servant.</p>'},
{id:'kpk-c10-eng-ch13-l3', title:'Vocabulary and Character', html:'<h3>Character</h3><p><strong>Firm, just, simple, God-fearing, tireless.</strong> He was martyred by <strong>Abu Lulu Firoz</strong> while leading the Fajr prayer.</p><h3>Vocabulary</h3><ul><li><strong>Caliph</strong> — successor/leader; <strong>justice</strong> — fairness; <strong>simplicity</strong> — plain living; <strong>martyr</strong> — one who dies for a cause.</li></ul>'}],
quiz:[
{q:'Hazrat Umar (R.A) was the ___ rightly-guided Caliph.', options:['First','Second','Third','Fourth'], answer:1, explain:'After Hazrat Abu Bakr (R.A).'},
{q:'He is most famous for his:', options:['Wealth','Justice','Poetry','Trade'], answer:1, explain:'His justice became proverbial.'},
{q:'“If a mule stumbles on the road to Iraq…” shows his:', options:['Fear of animals','Sense of responsibility','Love of travel','Anger'], answer:1, explain:'He felt answerable for every subject’s welfare.'},
{q:'The Hijri calendar was started by:', options:['Hazrat Abu Bakr (R.A)','Hazrat Umar (R.A)','Hazrat Usman (R.A)','Hazrat Ali (R.A)'], answer:1, explain:'His great administrative reform.'},
{q:'The Diwan was a:', options:['Court of music','State register of revenues and stipends','Army','Mosque'], answer:1, explain:'It organised the state’s finances.'},
{q:'He entered Jerusalem:', options:['On a horse, alone','On foot, sharing his camel with his servant','In a chariot','With an army parade'], answer:1, explain:'His humility amazed the people.'},
{q:'What kind of life did Hazrat Umar (R.A) lead?', options:['Luxurious','Extremely simple','Military only','Secluded'], answer:1, explain:'Patched clothes despite ruling an empire.'},
{q:'He was martyred by:', options:['A Roman soldier','Abu Lulu Firoz','A Persian king','An accident'], answer:1, explain:'Stabbed during the Fajr prayer.'},
{q:'Qazi courts were set up to ensure:', options:['Tax collection','Justice','Trade','Education'], answer:1, explain:'Independent judges across provinces.'},
{q:'His night rounds of Madina showed:', options:['Sleeplessness','Care for his people','Fear','Curiosity'], answer:1, explain:'He personally checked the citizens’ condition.'}
]},
{id:'kpk-c10-eng-ch14', title:'The Model Millionaire (Story)', urdu:'مثالی رئیس (کہانی)', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch14-l1', title:'The Story: Hughie’s Kindness', html:'<h3>Oscar Wilde’s Tale</h3><p><strong>Hughie Erskine</strong> is charming but poor — “he had every accomplishment except that of making money.” He loves <strong>Laura Merton</strong>, whose father demands <strong>£10,000</strong> before agreeing to the marriage.</p><h3>The Beggar</h3><p>Visiting his artist friend, Hughie sees a <strong>beggar-model</strong> posing. Moved with pity, Hughie gives the old man his <strong>last sovereign</strong> — all he has.</p>'},
{id:'kpk-c10-eng-ch14-l2', title:'The Twist', html:'<h3>The Beggar’s Identity</h3><p>The “beggar” is actually <strong>Baron Hausberg</strong>, one of the richest men in Europe! Touched by Hughie’s generosity, the Baron sends him a <strong>cheque for £10,000</strong> as a wedding present — with the note about “a model millionaire”.</p><h3>Message</h3><p><strong>Kindness is never wasted.</strong> Hughie’s selfless gift, given from his last coin, returns to him multiplied. True wealth is a generous heart.</p>'},
{id:'kpk-c10-eng-ch14-l3', title:'Vocabulary and Key Words', html:'<h3>Words to Master</h3><ul><li><strong>Ineffectual</strong> — not producing results.</li><li><strong>Sovereign</strong> — a gold coin (£1).</li><li><strong>Model</strong> — one who poses for artists.</li><li><strong>Generosity</strong> — giving freely.</li><li><strong>Romance</strong> — here, the charm of life (Wilde: “Romance is the privilege of the rich”).</li></ul>'}],
quiz:[
{q:'“The Model Millionaire” was written by:', options:['Charles Dickens','Oscar Wilde','Mark Twain','O. Henry'], answer:1, explain:'The Irish wit and storyteller.'},
{q:'Hughie Erskine is described as:', options:['Rich and rude','Charming but poor','Cruel and rich','Lazy and proud'], answer:1, explain:'“He had every accomplishment except that of making money.”'},
{q:'Laura’s father demands ___ before the marriage.', options:['£1,000','£10,000','£100','A house'], answer:1, explain:'Ten thousand pounds of his own.'},
{q:'Hughie gave the beggar:', options:['A shilling','His last sovereign','A coat','Nothing'], answer:1, explain:'All he had — a single gold sovereign.'},
{q:'The beggar was actually:', options:['A thief','Baron Hausberg, a millionaire','The artist','Laura’s father'], answer:1, explain:'The great twist of the tale.'},
{q:'The Baron sent Hughie:', options:['A thank-you note','A £10,000 wedding cheque','A painting','A job'], answer:1, explain:'Rewarding the generous “model millionaire”.'},
{q:'The story’s message is:', options:['Money buys love','Kindness is never wasted','Avoid beggars','Art pays well'], answer:1, explain:'Selfless generosity returns multiplied.'},
{q:'“Ineffectual” means:', options:['Effective','Not producing results','Cruel','Rich'], answer:1, explain:'Hughie’s charming ineffectualness.'},
{q:'A “sovereign” was a:', options:['King','Gold coin worth £1','Servant','Ship'], answer:1, explain:'The gold coin Hughie gave away.'},
{q:'Wilde’s opening line says romance is the privilege of the:', options:['Poor','Rich','Young','Brave'], answer:1, explain:'“Unless one is wealthy there is no use in being a charming fellow.”'}
]},
{id:'kpk-c10-eng-ch15', title:'Opportunity (Poem)', urdu:'موقع (نظم)', comingSoon:false, lessons:[
{id:'kpk-c10-eng-ch15-l1', title:'The Poet and the Poem', html:'<h3>Walter Malone</h3><p><strong>Walter Malone’s</strong> “Opportunity” personifies <strong>Opportunity</strong> as a visitor at every door.</p><h3>The Poem’s Voice</h3><p>Opportunity protests: <em>“They do me wrong who say I come no more”</em> — it <strong>knocks every day</strong> at every gate, bidding us <strong>wake, rise, fight and win</strong>. Those who miss it blame fate, but the fault is their own sleep.</p>'},
{id:'kpk-c10-eng-ch15-l2', title:'Explanation', html:'<h3>Stanza-wise</h3><ul><li>Opportunity <strong>comes repeatedly</strong>, not once.</li><li>It finds the <strong>sleeping and the dreaming</strong> unready.</li><li>The <strong>watchful and the brave</strong> seize it and rise.</li></ul><h3>Message</h3><p><strong>Opportunities come to everyone — success belongs to those awake enough to seize them.</strong> Do not blame luck; blame unreadiness.</p>'},
{id:'kpk-c10-eng-ch15-l3', title:'Figures of Speech and Vocabulary', html:'<h3>Figures of Speech</h3><ul><li><strong>Personification:</strong> Opportunity speaks and knocks.</li><li><strong>Repetition:</strong> the knock at every door.</li></ul><h3>Vocabulary</h3><ul><li><strong>Opportunity</strong> — a favourable chance; <strong>bid</strong> — command; <strong>seize</strong> — grab.</li></ul>'}],
quiz:[
{q:'“Opportunity” was written by:', options:['Walter Scott','Walter Malone','Walt Whitman','Wordsworth'], answer:1, explain:'Walter Malone’s famous poem.'},
{q:'In the poem, Opportunity is:', options:['A man','Personified as a visitor knocking at doors','A bird','A dream'], answer:1, explain:'It speaks: “They do me wrong who say I come no more.”'},
{q:'Opportunity claims it comes:', options:['Once in a lifetime','Every day to every door','Only to the rich','Never'], answer:1, explain:'It knocks daily; we fail to answer.'},
{q:'Those who miss opportunity blame:', options:['Themselves','Fate/luck','Their friends','The poem'], answer:1, explain:'But the fault is their own unreadiness.'},
{q:'“Bid you wake, and rise to fight and win” — “bid” means:', options:['Offer money','Command','Invite to dinner','Sell'], answer:1, explain:'Bid = order or urge.'},
{q:'Success in the poem belongs to the:', options:['Rich','Watchful and brave','Lucky','Idle'], answer:1, explain:'Readiness seizes the knock.'},
{q:'Giving Opportunity a voice is:', options:['Simile','Personification','Hyperbole','Irony'], answer:1, explain:'An abstract idea speaks like a person.'},
{q:'The poem’s message is:', options:['Wait for luck','Seize opportunities — they come to all','Opportunity never comes','Sleep well'], answer:1, explain:'Be awake when chance knocks.'},
{q:'“Seize” means:', options:['Release','Grab','Lose','Hide'], answer:1, explain:'Seize the day — carpe diem.'},
{q:'People “do Opportunity wrong” by saying:', options:['It is kind','It comes no more','It knocks loudly','It is unfair'], answer:1, explain:'The poem’s opening complaint.'}
]}
]});

